export const pilotSourceCommit="e21c22e5988f7cbb2ed37aadf3c6da9c7ea33ddc";
export const pilotAssets={
  "index.html": "<!doctype html><html lang=\"it\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"theme-color\" content=\"#155e72\"><meta name=\"apple-mobile-web-app-capable\" content=\"yes\"><meta name=\"apple-mobile-web-app-title\" content=\"Tagliando\"><meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\"><link rel=\"manifest\" href=\"./manifest.webmanifest\"><link rel=\"apple-touch-icon\" href=\"./icons/apple-touch-icon.png\"><link rel=\"stylesheet\" href=\"./style.css\"><title>Assistente di officina · Tagliando v0.12.0</title></head>\n<body><main><header><strong>◈ ASSISTENTE DI OFFICINA</strong><span class=\"pill\" id=\"version\">v0.12.1 · KB 14.3 test</span></header><h1>Tagliando guidato</h1><p class=\"muted\">Manutenzione preventiva del rasaerba a benzina. Otto lavorazioni consigliate, tutte facoltative. Le riparazioni sono attività separate.</p><div class=\"caution\"><strong>Prototipo sperimentale.</strong> Le istruzioni devono essere confrontate con il manuale del modello effettivo. Le indicazioni contrassegnate come specifiche del modello non possono essere considerate universalmente valide. In caso di rischio o dubbio tecnico, sospendi l'intervento.</div><div class=\"system\" id=\"system\" role=\"status\">Caricamento dell'applicazione…</div>\n<section class=\"panel\"><h2>Macchina e sessione</h2><div class=\"columns\"><div><label for=\"brand\">Marca e modello</label><input id=\"brand\" placeholder=\"Es. Honda HRG 466\"></div><div><label for=\"engine\">Motore / sigla (facoltativo)</label><input id=\"engine\" placeholder=\"Es. GCVx 145\"></div></div><p class=\"muted small\">Questi dati identificano la macchina nel rapporto: non verificano automaticamente le specifiche tecniche.</p></section>\n<div class=\"layout\"><div><section class=\"panel\"><div class=\"headrow\"><span class=\"kicker\" id=\"counter\"></span><span class=\"state\" id=\"state\"></span></div><div class=\"progress\"><div id=\"progressFill\"></div></div><h2 id=\"opTitle\"></h2><p id=\"opGoal\"></p><p class=\"muted small\" id=\"opContext\"></p><div class=\"choice\"><label for=\"method\">Modalità per questa lavorazione</label><select id=\"method\"></select></div><div class=\"headrow\"><h3>Guida passo per passo</h3><span class=\"state\" id=\"stepState\"></span></div><button id=\"benchToggle\" class=\"bench-toggle\" aria-pressed=\"false\">Attiva modalità banco · testo grande</button><div class=\"step\" id=\"stepPanel\"><div class=\"kicker\" id=\"stepCount\"></div><h3 id=\"stepTitle\"></h3><p id=\"stepText\"></p><p class=\"note\" id=\"stepCaution\"></p><p class=\"muted small\" id=\"stepSource\"></p><div class=\"actions\"><button id=\"stepPrev\">← Passo precedente</button><button id=\"stepConfirm\" class=\"primary\">Passaggio eseguito →</button><button id=\"stepUndo\" hidden>Annulla conferma</button><button id=\"stepNext\">Passo successivo →</button></div><p class=\"muted small\" id=\"stepProgress\"></p><div id=\"benchActions\" hidden><p class=\"muted small\">Conferma esclusivamente i passaggi realmente eseguiti o verificati.</p><div class=\"bench-controls\"><button id=\"benchPrev\">← Indietro</button><button id=\"benchConfirm\" class=\"primary\">Passaggio eseguito →</button><button id=\"benchNext\">Avanti →</button></div><button id=\"benchUndo\" hidden>Annulla conferma di questo passaggio</button><button id=\"benchExit\">Chiudi modalità banco</button></div></div><label for=\"note\">Note dell'operatore</label><textarea id=\"note\" placeholder=\"Risultato, materiali impiegati, eventuali osservazioni…\"></textarea><div id=\"anomalyArea\" hidden><label for=\"anomalyText\">Descrivi l'anomalia osservata</label><textarea id=\"anomalyText\" placeholder=\"Quale anomalia? Dove? Quale intervento resta da eseguire?\"></textarea><div class=\"actions\"><button class=\"danger\" id=\"anomalySave\">Registra e sospendi</button><button id=\"anomalyCancel\">Annulla</button></div></div><div class=\"actions\"><button class=\"primary\" id=\"complete\">Segna completata</button><button id=\"skip\">Salta operazione</button><button class=\"danger\" id=\"anomalyStart\">Segnala anomalia</button></div><div class=\"actions\"><button id=\"opPrev\">← Operazione precedente</button><button id=\"opNext\">Operazione successiva →</button></div></section><section class=\"panel\"><h2>Riepilogo della sessione</h2><p id=\"summary\"></p><p class=\"muted small\">Le operazioni saltate restano facoltative. Le anomalie sospese non equivalgono a riparazioni eseguite né a macchina dichiarata sicura.</p><div class=\"actions\"><button class=\"primary\" id=\"exportJSON\">Esporta JSON</button><button id=\"exportTXT\">Esporta rapporto TXT</button><button class=\"danger\" id=\"reset\">Azzera sessione</button></div><p class=\"muted small\">I dati sono memorizzati localmente su questo dispositivo. Prima di rimuovere l'app o i dati di Safari esporta una copia.</p></section></div><aside><section class=\"panel\"><h2>Operazioni</h2><ol id=\"operations\" class=\"oplist\"></ol></section><section class=\"panel\"><h2>Registro eventi</h2><div id=\"events\" class=\"events\" aria-live=\"polite\"></div></section></aside></div><section class=\"panel voice-panel\" id=\"voicePanel\"><h2>Dialogo vocale · v0.12.1 sperimentale</h2><p class=\"muted small\">Avvia il ciclo con un solo tocco. L'app legge il passaggio, prova ad ascoltare la risposta e, dopo «Fatto», legge quello successivo. La modalità pausa mantiene l’ascolto soltanto finché il browser lo consente; dopo un silenzio prolungato potrebbe richiedere un tocco.</p><div class=\"voice-actions\"><button id=\"voiceDialog\" class=\"primary\" type=\"button\">🎙 Avvia dialogo</button><button id=\"voiceListen\" type=\"button\">Ascolta un comando</button><button id=\"voiceRead\" type=\"button\">🔊 Leggi passaggio</button><button id=\"voiceStop\" class=\"danger\" type=\"button\">■ Ferma dialogo</button></div><p id=\"voiceStatus\" class=\"voice-status\" role=\"status\" aria-live=\"polite\">Modulo in inizializzazione…</p><p id=\"voiceHeard\" class=\"muted small\" aria-live=\"polite\"></p><p id=\"voiceAnomalyDraft\" class=\"note\" aria-live=\"polite\" hidden></p><p class=\"muted small\"><strong>Comandi:</strong> «Fatto», «Ho finito», «Ripeti», «Indietro», «Aspetta», «Riprendiamo», «Spiegami meglio», «Segnala un problema». Puoi anche chiedere «Quali precauzioni?», «Qual è lo scopo?», «Che modalità?» e «A che punto siamo?». Le difficoltà riconosciute ricevono risposte predefinite legate alla lavorazione. Le frasi ambigue come «Fatto, ma ho un problema» non confermano il passaggio. Le richieste sconosciute non cambiano il registro. Le spiegazioni rileggono soltanto informazioni presenti nella procedura. Le anomalie si possono descrivere, confermare e registrare interamente a voce: «Segnala un problema», descrizione, «Registra». Una segnalazione sospende la lavorazione senza confermarla.</p><p class=\"muted small\"><strong>Sicurezza:</strong> sperimenta a motore spento, senza lame in movimento e in un ambiente sicuro. È possibile interrompere il dialogo in qualsiasi momento. L'ascolto non è garantito in background o offline.</p></section><footer>Versione 0.12.1 · Prototipo di manutenzione preventiva · Nessuna diagnosi automatica o certificazione del lavoro.</footer></main><script src=\"./app.js\" defer></script><script src=\"./support.js\" defer></script><script src=\"./voice.js\" defer></script><script src=\"./knowledge.js\" defer></script><script src=\"./retrieval.js\" defer></script><script src=\"./knowledge-ui.js\" defer></script></body></html>\n",
  "app.js": "'use strict';\n// L'archivio descrive una guida prototipale basata sulle pratiche dell'esperto.\n// I passaggi tecnici modello-specifici vanno verificati sul manuale prima dell'esecuzione.\nconst OP=[\n{id:1,title:'Pulizia del sottoscocca',goal:'Rimuovere croste di terra ed erba dal soffitto interno e dai passaggi dell’aria per recuperare l’efficienza di taglio e raccolta.',context:'La pulizia a secco è più rapida; quella con acqua può risultare più approfondita.',methods:[['secco','Pulizia a secco'],['acqua','Pulizia con acqua (se consentita)']],steps:[\n['Preparazione','Identifica macchina e motore, attendi il raffreddamento, verifica arresto completo e protezione dall’avviamento accidentale.','Non accedere al sottoscocca se non puoi mettere in sicurezza la macchina.'],\n['Accesso al sottoscocca','Nel metodo di officina descritto si solleva il fronte della macchina e la si appoggia posteriormente, mantenendo la candela in alto. Verifica prima compatibilità con il modello, stabilità e possibili perdite.','L’orientamento deve rispettare il manuale del motore; non assumere che candela e filtro abbiano sempre la stessa posizione.'],\n['Rimozione incrostazioni','Rimuovi erba e terra da soffitto e condotto dell’aria del sottoscocca utilizzando utensili idonei e senza danneggiare scocca, protezioni o lama.','Non mettere le mani sul tagliente. Fermati se trovi danni che rendono l’intervento non sicuro.'],\n['Pulizia finale','Completa a secco con spazzola e rimozione dei residui oppure, se hai scelto il lavaggio e il costruttore lo consente, usa acqua senza dirigere getti in cuscinetti, aspirazione, comandi o componenti elettrici.','L’idropulitrice non va applicata indiscriminatamente: verifica sempre le istruzioni specifiche.', 'acqua|secco'],\n['Asciugatura','Se hai usato acqua, asciuga preferibilmente con aria compressa controllata, evitando getti sulle parti sensibili. Se hai lavorato a secco, verifica l’assenza di residui e umidità.','L’avviamento del motore per asciugare è una pratica riferita dall’esperto, non un’istruzione automatica del prototipo.'],\n['Controllo della scocca','Controlla che le croste siano state eliminate e che non ci siano crepe, fori o danni evidenti. Registra eventuali riparazioni da fare separatamente.','In presenza di danni strutturali o di sicurezza, sospendi e registra l’anomalia.']\n]},\n{id:2,title:'Affilatura della lama',goal:'Preparare i taglienti per la stagione successiva, mantenendo il corretto montaggio e la sicurezza del gruppo di taglio.',context:'Attrezzi di officina: pistola a impulsi, smerigliatrice angolare e disco lamellare grana 60–80. Questo prototipo non autorizza l’uso di utensili non conosciuti.',methods:[['standard','Affilatura e controllo']],steps:[\n['Messa in sicurezza','Identifica la lama, arresta il motore, scollega la pipetta secondo il manuale, immobilizza in sicurezza la macchina e usa protezioni adeguate.','La lama può tagliare anche se apparentemente poco affilata.'],\n['Smontaggio','Rimuovi il fissaggio con attrezzo adatto, immobilizzando la lama senza afferrarne i taglienti. Verifica la sequenza di rondelle e distanziali.','Se il fissaggio è bloccato, non forzare rischiando lesioni o danni.'],\n['Mozzo e linguetta','Controlla se il mozzo portalama si è sfilato e se la linguetta (“fiecca”), quando presente, è rimasta nella sua sede. Verifica integrità e corretto accoppiamento.','Se la linguetta o il mozzo sono deformati, crepati o usurati, non rimontare come se fossero sani.'],\n['Ispezione lama','Controlla che non siano presenti crepe, deformazioni gravi o consumo eccessivo. Prima dell’affilatura decidi se la lama è recuperabile.','Una lama compromessa va sostituita, non riaffilata.'],\n['Ripristino del tagliente','L’esperto segue l’angolo originale quando riconoscibile; in alternativa usa indicativamente 30–35° per lame compatibili, lavorando sui due taglienti dalla faccia superiore.','Angolo, geometria e limiti di usura sono specifici della lama. Evita surriscaldamento e asportazione eccessiva di materiale.'],\n['Equilibratura','Verifica il bilanciamento con un supporto appropriato sul foro centrale; nel metodo di officina esperto il controllo veniva riservato ai casi dubbi.','Per utenti non esperti è consigliabile verificarlo sempre; non usare un dito come supporto a contatto con il tagliente.'],\n['Montaggio e serraggio','Alloggia correttamente la lama nella sede di centraggio del mozzo, riposiziona eventuale linguetta e dispositivi di fissaggio. Serra secondo la coppia prescritta dal costruttore.','La regolazione “media” della pistola a impulsi non corrisponde a una coppia verificata. Usa il metodo e la coppia prescritti.'],\n['Verifica finale','Con il motore non avviabile, verifica il corretto fissaggio e l’assenza di interferenze con una rotazione manuale controllata della lama, senza afferrare il tagliente.','Se si avvertono giochi, interferenze o anomalie, non avviare la macchina.']\n]},\n{id:3,title:'Filtro dell’aria',goal:'Ripristinare filtraggio e flusso d’aria verso il motore.',context:'Filtri in carta e in spugna richiedono trattamenti diversi. Pulire sempre anche la scatola filtro.',methods:[['carta','Filtro in carta'],['spugna','Filtro in spugna'],['misto','Filtro carta con prefiltro spugna']],steps:[\n['Preparazione e apertura','A motore spento e freddo, identifica il tipo di filtro e apri la scatola filtro secondo il sistema di fissaggio presente.','Proteggi l’ingresso al carburatore da polvere e sporco durante la manutenzione.'],\n['Valutazione del materiale','Controlla lo stato dell’elemento. Il filtro in carta viene normalmente sostituito nel tagliando, tranne quando è stato montato recentemente ed è ancora integro. La spugna si riutilizza solo se morbida e non sgretolata.','Non trattare con liquidi un elemento in carta non lavabile.'],\n['Trattamento carta','Per carta: sostituisci con elemento compatibile, oppure conserva quello recente se pulito e idoneo. Per filtro misto, tratta la carta separatamente dalla spugna.','Non soffiare aggressivamente né lavare la carta se il costruttore non lo prevede.','carta|misto'],\n['Lavaggio spugna','Per spugna: utilizza detergente compatibile per filtri, risciacqua se previsto e lascia asciugare completamente. Sostituisci se indurita, friabile o deformata.','Il gasolio è citato come pratica d’officina, ma non è proposto come detergente standard dell’app.','spugna|misto'],\n['Oliatura spugna','Quando prevista per quello specifico elemento, distribuisci olio filtri spray oppure olio motore pulito, eliminando l’eccesso secondo le indicazioni del produttore.','Non tutti i prefiltri in spugna devono essere oliati; verifica il tipo.','spugna|misto'],\n['Pulizia scatola filtro','Pulisci scatola, coperchio e area vicina all’ingresso d’aria; rimuovi residui di olio e polvere evitando di introdurli nel carburatore.','Usa solo detergenti compatibili con plastica, guarnizioni e componenti vicini.'],\n['Rimontaggio','Inserisci gli elementi nel verso giusto e chiudi la scatola filtro. Verifica l’aderenza e l’assenza di aperture involontarie.','Non avviare il motore senza il filtro previsto correttamente installato.']\n]},\n{id:4,title:'Sostituzione della candela',goal:'Rinnovare la candela di accensione durante il tagliando stagionale.',context:'Codice candela, distanza elettrodi e serraggio dipendono dal motore e dal tipo di candela.',methods:[['standard','Sostituzione candela']],steps:[\n['Verifica ricambio','Identifica una candela nuova con caratteristiche e codice corrispondenti a quelli prescritti dal costruttore del motore.','Non basarti soltanto sulla somiglianza esteriore.'],\n['Rimozione','Su motore spento e freddo, stacca la pipetta e svita la candela con chiave adatta. Evita contaminazioni del foro della testata.','Non lavorare con testata calda.'],\n['Controllo sede e candela','Ispeziona filetto e sede; verifica eventuale distanza elettrodi se richiesta e lo stato del terminale superiore.','Se il filetto nella testata è danneggiato, fermati e richiedi riparazione qualificata.'],\n['Avvitamento iniziale','Inizia SEMPRE l’avvitamento della candela a mano, senza utensili a impulsi, per evitare imbocchi incrociati.','Se incontra resistenza anomala, non forzare.'],\n['Serraggio finale','Completa con coppia o angolo di serraggio previsto per candela e testata; la rondella di tenuta va compressa secondo le istruzioni specifiche.','I riferimenti empirici di mezzo giro o 15–25 Nm non sono universali.'],\n['Pipetta e prova','Ricollega saldamente la pipetta. Quando la macchina è completamente sicura e pronta all’avviamento, verifica il normale funzionamento.','Se non parte, controlla prima collegamento pipetta e compatibilità del ricambio; non procedere a diagnosi automatica.']\n]},\n{id:5,title:'Lubrificazione delle ruote',goal:'Favorire una rotazione libera delle ruote evitando attriti e giochi anomali.',context:'Il trattamento varia tra boccole, cuscinetti aperti e cuscinetti sigillati.',methods:[['boccola','Ruote con boccola'],['aperto','Cuscinetti aperti'],['sigillato','Cuscinetti sigillati']],steps:[\n['Sostegno stabile','Spegni e metti in sicurezza il rasaerba; sostienilo con supporti adeguati, lasciando le ruote libere.','Non affidarti a supporti instabili o improvvisati.'],\n['Smontaggio ruota','Lavora su una ruota alla volta. Se presente, rimuovi la borchia, quindi dado e ruota; conserva correttamente tutti i componenti.','Attenzione a dadi autobloccanti e piccoli fermi.'],\n['Lubrificazione boccole','Applica un sottile velo di grasso appropriato sul perno e nella boccola pulita, se previsti dalla configurazione.','Non contaminare superfici che il costruttore prescrive asciutte.','boccola'],\n['Lubrificazione cuscinetti aperti','Se le sfere sono visibili e accessibili e il costruttore ammette il trattamento, applica poche gocce di lubrificante compatibile.','Non smontare cuscinetti pressati o trattenuti da seeger senza attrezzatura e procedura adeguate.','aperto'],\n['Controllo cuscinetti sigillati','Verifica la libera rotazione del cuscinetto senza tentare di aprirlo per lubrificarlo. Se ruvido o bloccato, annota la necessità di sostituzione.','Non perforare né rimuovere schermature di cuscinetti sigillati.','sigillato'],\n['Montaggio ruota','Rimonta in sequenza gli elementi e serra secondo il sistema di fissaggio previsto; se necessario sostituisci dadi autobloccanti usurati.','Non allentare un dado per compensare una ruota frenata se così si perde il bloccaggio sicuro.'],\n['Controllo finale','Verifica che ogni ruota giri liberamente senza gioco eccessivo. Eventuali problemi alla trasmissione o agli ingranaggi vanno registrati separatamente.','L’eventuale lubrificazione della trasmissione richiede compatibilità con materiali e specifiche del gruppo.']\n]},\n{id:6,title:'Controllo viti e cavi',goal:'Verificare fissaggi e corretto funzionamento dei comandi, compresa la leva di arresto motore.',context:'Nessun cronometro richiesto nel tagliando ordinario; devono essere rispettati i requisiti di sicurezza del modello.',methods:[['standard','Verifica cavi e fissaggi']],steps:[\n['Ispezione comandi','A motore spento, verifica guaine, cavi, molle e leveraggi della leva di sicurezza e, se presente, della trazione.','Se i cavi sono sfilacciati, arrugginiti, deformati o bloccati, sospendi e registra.'],\n['Controllo gioco cavi','Controlla il gioco e la corsa della leva. Se previsto dal costruttore, esegui regolazione mediante apposito registro senza impedire il fine corsa corretto.','Una regolazione errata del cavo di arresto può impedire lo spegnimento.'],\n['Viti e supporto motore','Verifica che i fissaggi accessibili, in particolare il supporto motore, non siano allentati. Esegui serraggi solo con valori e metodi previsti per il modello.','Fissaggi ripetutamente allentati possono indicare vibrazioni anomale da indagare separatamente.'],\n['Verifica funzionale sicurezza','Con macchina rimontata, area libera e condizioni idonee per avvio, verifica che il rilascio della leva di sicurezza arresti il motore.','Se il motore non si arresta correttamente, non utilizzare la macchina: apri anomalia di sicurezza.'],\n['Controllo conclusivo','Verifica normale scorrimento dei comandi e assenza di parti mobili o fissaggi anomali; registra problemi di trazione per intervento separato.','Il funzionamento del comando non sostituisce eventuali requisiti del costruttore sul tempo di arresto della lama.']\n]},\n{id:7,title:'Sostituzione olio motore',goal:'Rimuovere l’olio usato e riportare il livello al valore previsto dal costruttore.',context:'L’esperto privilegia la pompa aspirante; scarico inferiore soltanto quando appropriato.',methods:[['aspira','Aspirazione con pompa'],['scarico','Scarico da tappo (se previsto)']],steps:[\n['Identificazione olio e capacità','Verifica sul manuale la gradazione, la capacità, l’intervallo e il metodo corretto di lettura dell’astina. Prepara recipiente idoneo per olio esausto.','SAE 30/10W-40 e 450–530 ml sono esempi ricorrenti nell’esperienza d’officina, non valori universali.'],\n['Preparazione','Se previsto, porta il motore a temperatura moderata, poi spegnilo, attendi e previeni riavviamenti accidentali.','Attenzione alle superfici calde e all’olio che può provocare ustioni.'],\n['Estrazione con pompa','Apri il bocchettone e aspira attraverso la cannula fino a rimuovere l’olio secondo le possibilità del modello. Eventuale lieve rialzo frontale richiede stabilità e autorizzazione del manuale.','Non forzare la cannula né assumere che tutti i motori consentano aspirazione completa.','aspira'],\n['Scarico tramite tappo','Solo se il manuale prevede lo scarico inferiore e sono disponibili attrezzi, guarnizioni e contenitore corretti: scarica e richiudi con serraggio previsto.','Teste particolari e guarnizioni delicate possono danneggiarsi: se non hai i ricambi adeguati, non procedere.','scarico'],\n['Rifornimento','Aggiungi olio idoneo in quantità graduale, tenendoti inizialmente sotto la capacità nominale e verificando via via il livello.','Non versare quantità a occhio e non avviare il motore senza olio.'],\n['Misura livello','Misura con il sistema prescritto dal motore: su alcuni modelli l’astina si avvita, su altri si appoggia. Resta entro i riferimenti min/max.','Non presumere il metodo di lettura in base alla sola marca.'],\n['Chiusura e verifica','Chiudi il tappo, pulisci eventuali tracce d’olio e verifica l’assenza di perdite. Smaltisci l’olio usato presso punto di raccolta autorizzato.','Se ci sono perdite dal basamento o dall’albero, sospendi e registra un problema distinto.']\n]},\n{id:8,title:'Carburante e rimessaggio',goal:'Ridurre i problemi di riavvio dopo un lungo periodo di inutilizzo.',context:'Le indicazioni del costruttore possono prevedere svuotamento o carburante fresco con stabilizzante. Non miscelare procedure incompatibili.',methods:[['esaurimento','Consumo controllato carburante residuo'],['drenaggio','Drenaggio vaschetta (se previsto)'],['manuale','Procedura alternativa da manuale']],steps:[\n['Piano rimessaggio','Verifica la procedura prevista per il motore: serbatoio vuoto, vaschetta drenata oppure carburante stabilizzato secondo specifica.','Non presumere che svuotare tutto sia obbligatorio per ogni modello.'],\n['Preparazione area','Lavora all’aperto o in ambiente ventilato idoneo, lontano da fiamme, scintille, sigarette e superfici calde. Prepara un contenitore omologato e un sistema contro gli sversamenti.','La benzina è molto infiammabile; non usare bottiglie o contenitori improvvisati.'],\n['Rimozione carburante serbatoio','Se è prevista la rimozione, aspira il carburante con attrezzatura idonea a benzina e richiudi il serbatoio. Verifica il corretto smaltimento o riutilizzo consentito.','Non usare pompe o utensili elettrici non certificati per liquidi infiammabili.','esaurimento|drenaggio'],\n['Esaurimento controllato','Solo quando previsto dal costruttore e con macchina montata e in condizioni operative sicure, puoi interrompere l’alimentazione e lasciare funzionare il motore fino allo spegnimento spontaneo.','Non garantisce necessariamente il drenaggio completo della vaschetta. Non operare in locali chiusi per rischio monossido.','esaurimento'],\n['Drenaggio vaschetta','A motore spento e freddo, se è presente una vite di drenaggio prevista dal manuale, predisponi una raccolta che eviti cadute di benzina a terra e procedi solo se hai accesso sicuro.','Se manca spazio o non puoi raccogliere il carburante senza sversamenti, non intervenire.','drenaggio'],\n['Metodo alternativo','Seleziona la procedura di rimessaggio alternativa esattamente come riportata dal manuale per quel motore (per esempio carburante fresco con stabilizzante approvato).','Questa modalità non prescrive automaticamente quantità o prodotti.','manuale'],\n['Controllo finale','Verifica chiusura dei tappi, posizione del rubinetto, assenza di perdite e condizioni idonee al deposito. Registra il metodo utilizzato.','Se rilevi perdite o odori persistenti di carburante, sospendi e intervieni in sicurezza.']\n]}\n];\nfunction stepsFor(idx){const op=OP[idx],method=state.methods[idx];return op.steps.filter(s=>!s[3]||s[3].split('|').includes(method));}\nconst $=id=>document.getElementById(id);\nconst storageKey='tagliando-pwa-v05-session',oldKey='tagliando-pwa-v04-session';\nconst labels={pending:'Da eseguire',done:'Completata',skipped:'Saltata',stopped:'Sospesa — anomalia'};\nconst defaults=()=>({version:2,machine:{model:'',engine:''},current:0,records:OP.map(o=>({status:'pending',note:'',anomaly:'',updatedAt:null,method:o.methods[0][0],confirmed:{},step:0})),methods:OP.map(o=>o.methods[0][0]),events:[]});\nlet state=defaults();\nfunction normalizeSaved(raw){const s=defaults();if(!raw||!Array.isArray(raw.records)||raw.records.length!==OP.length)return s;s.machine={model:String(raw.machine?.model||''),engine:String(raw.machine?.engine||'')};s.current=Math.min(OP.length-1,Math.max(0,Number(raw.current)||0));s.events=Array.isArray(raw.events)?raw.events.slice(-250):[];s.records=s.records.map((r,i)=>{const prev=raw.records[i]||{};r.status=Object.hasOwn(labels,prev.status)?prev.status:'pending';r.note=String(prev.note||'');r.anomaly=String(prev.anomaly||'');r.updatedAt=prev.updatedAt||null;r.method=OP[i].methods.some(m=>m[0]===prev.method)?prev.method:OP[i].methods[0][0];r.confirmed=prev.confirmed&&typeof prev.confirmed==='object'&&!Array.isArray(prev.confirmed)?prev.confirmed:{};r.step=Number(prev.step)||0;return r});s.methods=s.records.map(r=>r.method);return s;}\nfunction load(){let migrated=false;try{let raw=localStorage.getItem(storageKey);if(raw){state=normalizeSaved(JSON.parse(raw));return 'Sessione v0.5 recuperata.';}raw=localStorage.getItem(oldKey);if(raw){const old=JSON.parse(raw);state=normalizeSaved(old);if(old.guided?.confirmed?.length===6){for(let i=0;i<6;i++)if(old.guided.confirmed[i])state.records[0].confirmed['old-'+(i+1)]=true;}migrated=true;localStorage.setItem(storageKey,JSON.stringify(state));return migrated?'Sessione v0.4 importata. Le conferme dei nuovi passaggi devono essere rivalidate.':'';}}catch(e){return 'Impossibile recuperare la sessione precedente: esporta un backup prima di azzerare.';}return 'Nuova sessione. Salvataggio automatico locale attivo.';}\nfunction save(){state.machine={model:$('brand').value,engine:$('engine').value};state.records[state.current].note=$('note').value;try{localStorage.setItem(storageKey,JSON.stringify(state));$('system').textContent='Sessione salvata su questo dispositivo';}catch(e){$('system').textContent='Salvataggio locale non disponibile: esporta la scheda.';}}\nfunction log(action,index){state.events.push({timestamp:new Date().toISOString(),operationId:index+1,event:action});state.events=state.events.slice(-250);}\nfunction safeText(id,v){$(id).textContent=v;}\nfunction render(){const idx=state.current,r=state.records[idx],op=OP[idx],steps=stepsFor(idx);r.step=Math.min(Math.max(0,r.step),steps.length-1);safeText('counter',`Operazione ${idx+1} di ${OP.length}`);safeText('opTitle',op.title);safeText('opGoal',op.goal);safeText('opContext',op.context);safeText('state',labels[r.status]);$('state').className='state '+(r.status==='pending'?'':r.status);$('note').value=r.note;$('method').replaceChildren();op.methods.forEach(([v,label])=>{const option=document.createElement('option');option.value=v;option.textContent=label;$('method').append(option)});$('method').value=r.method;safeText('stepCount',`Passaggio ${r.step+1} di ${steps.length}`);const step=steps[r.step];safeText('stepTitle',step[0]);safeText('stepText',step[1]);safeText('stepCaution','ATTENZIONE · '+step[2]);safeText('stepSource','Procedura di riferimento: esperienza d’officina integrata con cautele e verifiche modello-specifiche.');safeText('stepState',r.confirmed[step[0]]?'Confermato':'Da confermare');$('stepState').className='state '+(r.confirmed[step[0]]?'done':'');const count=steps.filter(s=>r.confirmed[s[0]]).length;safeText('stepProgress',`${count} di ${steps.length} passaggi confermati nella modalità selezionata.`);$('stepPrev').disabled=r.step===0;$('stepNext').disabled=r.step===steps.length-1;$('benchPrev').disabled=r.step===0;$('benchNext').disabled=r.step===steps.length-1;$('benchConfirm').disabled=false;$('benchConfirm').textContent='Passaggio eseguito →';$('stepConfirm').textContent='Passaggio eseguito →';$('stepUndo').hidden=!r.confirmed[step[0]];$('benchUndo').hidden=!r.confirmed[step[0]];$('opPrev').disabled=idx===0;$('opNext').disabled=idx===OP.length-1;$('anomalyText').value=r.anomaly;$('anomalyArea').hidden=true;$('operations').replaceChildren();OP.forEach((o,i)=>{const li=document.createElement('li');li.className=i===idx?'active':'';li.tabIndex=0;li.setAttribute('role','button');li.textContent=`${i+1}. ${o.title}`;const small=document.createElement('span');small.textContent=labels[state.records[i].status];li.append(small);li.addEventListener('click',()=>move(i));li.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();move(i)}});$('operations').append(li)});const counts={};Object.keys(labels).forEach(k=>counts[k]=state.records.filter(x=>x.status===k).length);$('progressFill').style.width=`${100*(counts.done+counts.skipped+counts.stopped)/OP.length}%`;safeText('summary',`${counts.done} completate · ${counts.skipped} saltate · ${counts.stopped} sospese per anomalia · ${counts.pending} da decidere.`);$('events').replaceChildren();state.events.slice().reverse().slice(0,22).forEach(e=>{const p=document.createElement('p');p.textContent=`${new Date(e.timestamp).toLocaleString('it-IT')} · ${e.operationId}: ${labels[e.event]||e.event}`;$('events').append(p)});}\nfunction move(idx){state.records[state.current].note=$('note').value;state.current=idx;render();save();}\nfunction complete(){const idx=state.current,r=state.records[idx],steps=stepsFor(idx);if(!steps.every(s=>r.confirmed[s[0]])){alert('Per segnare completata la lavorazione, conferma tutti i suoi passaggi oppure scegli «Salta operazione».');return;}setStatus('done');}\nfunction setStatus(status){const idx=state.current,r=state.records[idx];r.status=status;r.note=$('note').value;r.updatedAt=new Date().toISOString();log(status,idx);const advance=idx<OP.length-1;state.current=advance?idx+1:idx;render();save();if(advance){$('counter').scrollIntoView({behavior:'smooth',block:'start'});}else{$('summary').scrollIntoView({behavior:'smooth',block:'center'});}}\n// API controllata usata dal dialogo vocale: registra e sospende SENZA avanzare\n// automaticamente alla lavorazione successiva. Nessuna conferma di passaggio implicita.\nfunction recordVoiceAnomaly(description){\n const text=String(description||'').trim().slice(0,450);\n if(text.length<5) return {ok:false,reason:'Descrizione troppo breve.'};\n const idx=state.current,r=state.records[idx];\n const timestamp=new Date().toISOString();\n r.anomaly=r.anomaly?`${r.anomaly}\\n[${timestamp} · segnalazione vocale] ${text}`:text;\n r.status='stopped';\n r.updatedAt=timestamp;\n r.note=$('note').value;\n log('stopped',idx);\n render();save();\n return {ok:true,operation:idx+1,title:OP[idx].title,description:text};\n}\nwindow.TagliandoApp={recordVoiceAnomaly};\nfunction exportSnapshot(){state.records[state.current].note=$('note').value;return {schemaVersion:'0.5',exportedAt:new Date().toISOString(),machine:{model:$('brand').value,engine:$('engine').value},module:'manutenzione_preventiva',notice:'Lavorazioni dichiarate dall’operatore. Nessuna certificazione tecnica o diagnosi automatica.',operations:OP.map((o,i)=>({id:o.id,title:o.title,status:state.records[i].status,notes:state.records[i].note,anomaly:state.records[i].anomaly,method:state.records[i].method,updatedAt:state.records[i].updatedAt,steps:stepsFor(i).map(s=>({title:s[0],confirmed:Boolean(state.records[i].confirmed[s[0]])}))})),events:state.events};}\nfunction download(name,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=name;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}\nlet benchMode=false;\nfunction setBenchMode(on){benchMode=Boolean(on);document.body.classList.toggle('bench-mode',benchMode);$('benchToggle').textContent=benchMode?'Modalità banco attiva · torna alla vista completa':'Attiva modalità banco · testo grande';$('benchToggle').setAttribute('aria-pressed',String(benchMode));$('benchActions').hidden=!benchMode;if(benchMode)$('stepPanel').scrollIntoView({block:'start'});}\nfunction bindBench(){\n$('benchToggle').onclick=()=>setBenchMode(!benchMode);\n$('benchExit').onclick=()=>setBenchMode(false);\n$('benchPrev').onclick=()=>{if(!$('stepPrev').disabled)$('stepPrev').click()};\n$('benchNext').onclick=()=>{if(!$('stepNext').disabled)$('stepNext').click()};\n$('benchConfirm').onclick=()=>confirmAndAdvance();\n$('benchUndo').onclick=()=>undoStep();\n}\n// Azioni condivise da vista completa e modalità banco. Una conferma non è mai un toggle.\nfunction undoStep(){\n const r=state.records[state.current],step=stepsFor(state.current)[r.step];\n if(!r.confirmed[step[0]])return;\n r.confirmed[step[0]]=false;\n if(r.status==='done')r.status='pending';\n render();save();\n}\nfunction confirmAndAdvance(){\n const idx=state.current,r=state.records[idx],steps=stepsFor(idx);\n if(!steps.length)return;\n const current=r.step,step=steps[current];\n r.confirmed[step[0]]=true;\n if(r.status==='done')r.status='pending';\n // Procedere anche quando il passaggio era già confermato in una sessione precedente.\n const nextMissing=steps.findIndex((s,i)=>i>current&&!r.confirmed[s[0]]);\n if(nextMissing>=0)r.step=nextMissing;\n else{\n  const anyMissing=steps.findIndex(s=>!r.confirmed[s[0]]);\n  if(anyMissing>=0)r.step=anyMissing;\n  else{setStatus('done');if(benchMode)$('stepPanel').scrollIntoView({block:'start'});return;}\n }\n render();save();\n if(benchMode)$('stepPanel').scrollIntoView({block:'start'});\n}\nfunction bind(){const message=load();$('brand').value=state.machine.model;$('engine').value=state.machine.engine;render();$('system').textContent=message;$('brand').addEventListener('input',save);$('engine').addEventListener('input',save);$('note').addEventListener('input',save);$('method').addEventListener('change',()=>{state.records[state.current].method=$('method').value;state.records[state.current].step=0;state.methods[state.current]=$('method').value;render();save()});$('stepPrev').onclick=()=>{state.records[state.current].step--;render();save()};$('stepNext').onclick=()=>{state.records[state.current].step++;render();save()};$('stepConfirm').onclick=()=>confirmAndAdvance();$('stepUndo').onclick=()=>undoStep();$('complete').onclick=complete;$('skip').onclick=()=>{if(confirm('Vuoi saltare questa lavorazione? Sarà registrata come non eseguita.'))setStatus('skipped')};$('anomalyStart').onclick=()=>{$('anomalyArea').hidden=false;$('anomalyText').focus()};$('anomalyCancel').onclick=()=>{$('anomalyArea').hidden=true};$('anomalySave').onclick=()=>{const v=$('anomalyText').value.trim();if(!v){alert('Descrivi prima l’anomalia.');return;}state.records[state.current].anomaly=v;setStatus('stopped')};$('opPrev').onclick=()=>move(state.current-1);$('opNext').onclick=()=>move(state.current+1);$('exportJSON').onclick=()=>download('tagliando-v05.json',JSON.stringify(exportSnapshot(),null,2),'application/json');$('exportTXT').onclick=()=>{const s=exportSnapshot(),txt=['RAPPORTO TAGLIANDO v0.5','Macchina: '+s.machine.model,'Motore: '+s.machine.engine,'Esportato: '+s.exportedAt,'PROTOTIPO — DATI DICHIARATI DALL’OPERATORE','',...s.operations.flatMap(o=>[`${o.id}. ${o.title} — ${labels[o.status]}`,`Modalità: ${o.method}`,`Note: ${o.notes||'—'}`,`Anomalia: ${o.anomaly||'—'}`,`Passaggi confermati: ${o.steps.filter(x=>x.confirmed).length}/${o.steps.length}`,''])].join('\\n');download('rapporto-tagliando-v05.txt',txt,'text/plain;charset=utf-8')};$('reset').onclick=()=>{if(confirm('Vuoi azzerare TUTTA la sessione v0.5, comprese le note? Esporta prima un backup.')){state=defaults();$('brand').value='';$('engine').value='';render();save()}};bindBench();document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')save()});window.addEventListener('pagehide',save);if('serviceWorker'in navigator&&(location.protocol==='https:'||location.hostname==='localhost')){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(reg=>reg.update()).catch(()=>{}));}}\nwindow.addEventListener('DOMContentLoaded',bind);\n",
  "support.js": "/* v0.11.0 - supporto contestuale deterministico. Non esegue diagnosi né inventa procedure. */\n(()=>{'use strict';\n const norm=s=>String(s||'').toLocaleLowerCase('it-IT').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').replace(/[^a-z0-9 ]/g,' ').replace(/\\s+/g,' ').trim();\n const has=(s,pattern)=>pattern.test(s);\n function resolve(transcript,context){\n  const s=norm(transcript),op=Number(context?.operation)||0;\n  if(!s||!op)return null;\n  // I segnali gravi hanno precedenza sulle domande di aiuto; non cambiano mai lo stato del tagliando.\n  const danger=[\n   {op:2,re:/\\b(lama|tagliente)\\b.*\\b(crep|fessur|rotta|spezzat|piegat)|\\b(crep|fessur|rotta|spezzat|piegat)\\w*.*\\b(lama|tagliente)\\b/,msg:'Interrompi l’intervento sulla lama. Non affilare né rimontare una lama lesionata, deformata o rotta. Serve una valutazione e, se necessario, la sostituzione con un ricambio idoneo.'},\n   {op:6,re:/\\b(leva|freno|comando|motore)\\b.*\\b(non si spegne|non spegne|resta acceso|non si ferma)|\\b(non si spegne|non spegne|resta acceso|non si ferma).*\\b(motore|leva)\\b/,msg:'Interrompi il tagliando operativo. Il comando di arresto deve funzionare correttamente. Non usare la macchina fino alla riparazione e alla verifica della funzione di sicurezza.'},\n   {op:4,re:/\\b(filettatura|filetto|sede candela)\\b.*\\b(spanat|rovinat|danneggiat)|\\b(spanat|rovinat|danneggiat)\\w*.*\\b(filettatura|filetto)\\b/,msg:'Interrompi il montaggio della candela. Non forzare la filettatura della testata: occorre una verifica tecnica prima di procedere.'},\n   {op:7,re:/\\b(perdita|perde|fuoriesce)\\b.*\\b(olio|motore)|\\b(olio|motore)\\b.*\\b(perdita|perde|fuoriesce)\\b/,msg:'Ferma la lavorazione e verifica la causa della perdita d’olio. Il tagliando non sostituisce un intervento di riparazione.'},\n   {op:8,re:/\\b(benzina|carburante)\\b.*\\b(perdita|perde|versat|terra|fuoriuscit)|\\b(perdita|perde|versat|fuoriuscit).*\\b(benzina|carburante)\\b/,msg:'Interrompi l’intervento. Allontana le fonti d’innesco, evita di avviare il motore e gestisci la perdita di carburante in sicurezza.'},\n  ];\n  for(const item of danger){if(item.op===op&&has(s,item.re))return {kind:'stop',message:item.msg};}\n  const help=[\n   {op:3,re:/\\b(coperchio|scatola filtro)\\b.*\\b(non riesco|non si apre|non viene|bloccato|incastrato|togliere|aprire)|\\b(non riesco|bloccato|incastrato)\\b.*\\b(coperchio|scatola filtro)\\b/,msg:'Per il coperchio della scatola filtro, controlla se è fissato da una vite o da linguette a incastro. Non forzare. Se il fissaggio non è riconoscibile, consulta il manuale del modello.'},\n   {op:3,re:/\\b(spugna|filtro)\\b.*\\b(dura|indurita|sgretola|sbriciola|rotta|danneggiata)|\\b(indurita|sgretola|sbriciola)\\b.*\\b(spugna|filtro)\\b/,msg:'Una spugna indurita, sgretolata o danneggiata deve essere sostituita. Non considerarla recuperabile con una semplice pulizia.'},\n   {op:2,re:/\\b(mozzo|linguetta|fiecca|chiavetta)\\b.*\\b(cadut|sfilat|uscit|persa)|\\b(cadut|sfilat|uscit|persa)\\w*.*\\b(mozzo|linguetta|fiecca|chiavetta)\\b/,msg:'Durante lo smontaggio il mozzo può sfilarsi. Controlla che linguetta e sedi siano presenti, integre e correttamente accoppiate. Se noti danni o non riconosci il montaggio, sospendi e verifica il manuale.'},\n   {op:2,re:/\\b(angolo|inclinazione)\\b.*\\b(lama|affilatura|tagliente)|\\b(lama|affilatura|tagliente)\\b.*\\b(angolo|inclinazione)\\b/,msg:'La procedura di officina segue l’angolo originale quando riconoscibile. Il riferimento di 30–35 gradi non è universale: prima di modificare il profilo verifica che sia compatibile con la lama.'},\n   {op:4,re:/\\b(quale|che|tipo|codice|modello)\\b.*\\b(candela)\\b|\\b(candela)\\b.*\\b(quale|codice|modello|compatibile)\\b/,msg:'Il codice, la distanza degli elettrodi e il serraggio della candela dipendono dal motore. Occorre identificare il modello e verificare le specifiche del costruttore.'},\n   {op:7,re:/\\b(quanto|quanta|quantita|quale|quanto ne)\\b.*\\b(olio|litri|millilitri)|\\b(olio)\\b.*\\b(quanto|quanta|mettere|versare|quantita)\\b/,msg:'La quantità e la gradazione dell’olio dipendono dal motore. Identifica il modello, consulta il manuale e controlla il livello secondo la procedura prescritta. Non usare una quantità generica.'},\n   {op:5,re:/\\b(ruota|cuscinetto|boccola)\\b.*\\b(bloccata|non gira|frenata|dura)|\\b(bloccata|non gira|frenata)\\b.*\\b(ruota|cuscinetto)\\b/,msg:'Verifica che la ruota possa girare liberamente e che il supporto sia integro. Un cuscinetto bloccato o danneggiato richiede valutazione e possibile sostituzione; non allentare un fissaggio fino a renderlo insicuro.'},\n   {op:8,re:/\\b(vaschetta|vite|carburatore)\\b.*\\b(scarico|drenaggio|svuotare)|\\b(scarico|drenaggio)\\b.*\\b(vaschetta|carburatore)\\b/,msg:'Il drenaggio dalla vaschetta è un’alternativa solo se prevista dal costruttore e con raccolta del carburante in contenitore idoneo. Non eseguire l’operazione con motore caldo o vicino a fonti d’innesco.'},\n  ];\n  for(const item of help){if(item.op===op&&has(s,item.re))return {kind:'answer',message:item.msg};}\n  if(/\\b(non riesco|e bloccato|si e rotto|cosa faccio|come faccio|perche non|non funziona|ho trovato|ho notato|posso usare|devo sostituire)\\b/.test(s)){\n    return {kind:'unknown',message:'Ho capito che segnali una difficoltà, ma non ho una risposta verificata per questo caso nella lavorazione attuale. Non forzare il componente. Puoi chiedere le precauzioni o interrompere e registrare l’anomalia.'};\n  }\n  return null;\n }\n window.TagliandoContextHelp={resolve,normalize:norm};\n})();\n",
  "voice.js": "/* v0.12.1 - segnalazioni completamente vocali; nessuna diagnosi AI. */\n(() => {\n 'use strict';\n const $=id=>document.getElementById(id);\n const Engine=window.SpeechRecognition||window.webkitSpeechRecognition;\n const synth=('speechSynthesis' in window)?window.speechSynthesis:null;\n let active=false, listening=false, recognition=null, speaking=false, paused=false;\n let turn=0, retries=0, lastResult=false, lastError='';\n let pendingRestart=null;\n let anomalyFlow=null; // {stage,description,critical,warning,operation}\n const setStatus=t=>{ $('voiceStatus').textContent=t; };\n const setHeard=t=>{ $('voiceHeard').textContent=t; };\n const setDraft=t=>{ const el=$('voiceAnomalyDraft');if(!el)return;el.textContent=t||'';el.hidden=!t; };\n function refreshButtons(){ $('voiceDialog').textContent=active?'Dialogo attivo':'🎙 Avvia dialogo';$('voiceDialog').disabled=active; $('voiceListen').disabled=listening; }\n function clearPending(){ if(pendingRestart!==null){clearTimeout(pendingRestart);pendingRestart=null;} }\n function abortRecognition(){const r=recognition;recognition=null;listening=false;if(r){r.onend=null;r.onerror=null;r.onresult=null;try{r.abort();}catch(_){}} refreshButtons();}\n function stopSpeech(){speaking=false;if(synth)try{synth.cancel();}catch(_){} }\n function stopAll(message='Dialogo interrotto. Puoi ripartire quando vuoi.'){\n   active=false;paused=false;anomalyFlow=null;setDraft('');turn++;clearPending();abortRecognition();stopSpeech();setStatus(message);refreshButtons();\n }\n function speechText(){\n   const op=$('opTitle')?.textContent||'Tagliando';\n   const step=$('stepTitle')?.textContent||'';\n   const instruction=$('stepText')?.textContent||'';\n   return `${op}. ${step}. ${instruction}`;\n }\n function say(text,next){\n   if(!synth||!window.SpeechSynthesisUtterance){setStatus('Lettura vocale non disponibile. Usa i pulsanti sullo schermo.');if(active)stopAll('Lettura non disponibile: dialogo fermato.');return;}\n   abortRecognition();stopSpeech();speaking=true;\n   let finished=false;const myTurn=turn;\n   const u=new SpeechSynthesisUtterance(text);u.lang='it-IT';u.rate=0.93;\n   const complete=(ok)=>{if(finished)return;finished=true;speaking=false;if(myTurn!==turn)return;if(!ok){stopAll('Sintesi vocale interrotta: usa i pulsanti manuali.');return;}if(typeof next==='function')next();};\n   u.onend=()=>complete(true);u.onerror=()=>complete(false);\n   try{synth.speak(u);}catch(_){complete(false);}\n }\n const normalize=s=>s.toLocaleLowerCase('it-IT').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').replace(/[^a-z ]/g,' ').replace(/\\s+/g,' ').trim();\n // Le frasi composte non devono mai trasformarsi in un completamento accidentale.\n // Si richiede esplicitamente all'utente di segnalare l'anomalia o di ripetere il comando.\n function ambiguousIntent(t){\n   const s=normalize(t);\n   const completion=/\\b(fatto|finito|completato|eseguito|procedi|prosegui|avanti)\\b/.test(s);\n   const difficulty=/\\b(ma|pero|problema|anomalia|rotto|rotta|crepa|crepata|guasto|non riesco|non funziona|bloccato|bloccata|dubbio)\\b/.test(s);\n   if(/\\b(non ho finito|non e finito|non e fatto|non ho completato|non e completato|non ancora finito)\\b/.test(s))return 'not-done';\n   if(completion&&difficulty)return 'mixed';\n   return null;\n }\n\n function commandFor(t){\n   const s=normalize(t);\n   if(/\\b(ferma dialogo|interrompi dialogo|stop dialogo|termina dialogo|fermati|stop)\\b/.test(s))return 'stop';\n   if(/\\b(segnala un problema|segnala problema|ho un problema|c e un problema|anomalia|segnala anomalia)\\b/.test(s))return 'anomaly';\n   if(/\\b(aspetta|attendi|un momento|un attimo|metti in pausa|pausa|ferma un attimo)\\b/.test(s))return 'pause';\n   if(/\\b(riprendiamo|riprendi|continuiamo|possiamo continuare|sono pronto|sono pronta|ricominciamo)\\b/.test(s))return 'resume';\n   if(/\\b(quali precauzioni|che precauzioni|quali rischi|cosa devo evitare|attenzione a cosa|avvertenze|sicurezza del passaggio)\\b/.test(s))return 'caution';\n   if(/\\b(qual e lo scopo|a cosa serve|perche questa operazione|perche lo facciamo|qual e l obiettivo|qual e il fine)\\b/.test(s))return 'purpose';\n   if(/\\b(che modalita|quale modalita|modalita selezionata|che metodo sto usando|quale metodo ho scelto)\\b/.test(s))return 'method';\n   if(/\\b(a che punto siamo|quanto manca|quanti passaggi mancano|quanti passaggi ho fatto|stato di avanzamento)\\b/.test(s))return 'progress';\n   if(/^(aiuto|cosa posso chiederti|quali comandi conosci|che comandi posso dire)$/.test(s))return 'help';\n   if(/\\b(non ho capito|spiegami meglio|cosa devo fare|che devo fare|puoi spiegare|chiarisci|spiegazione)\\b/.test(s))return 'explain';\n   if(/\\b(ripeti|ripeti passaggio|leggilo di nuovo|puoi ripetere|rileggi)\\b/.test(s))return 'repeat';\n   if(/\\b(indietro|torna indietro|precedente|passo precedente)\\b/.test(s))return 'back';\n   if(/^(fatto|ho fatto|eseguito|passaggio eseguito|ho finito|finito|si fatto|ok fatto|completato|ho completato|possiamo proseguire|andiamo avanti|passo successivo|procedi|prosegui|tutto fatto)$/.test(s))return 'done';\n   return null;\n }\n function explainStep(){\n   const title=$('stepTitle')?.textContent||'questo passaggio';\n   const instruction=$('stepText')?.textContent||'';\n   const caution=$('stepCaution')?.textContent||'';\n   // Mai generare nuove istruzioni: si leggono esclusivamente informazioni già visibili nella guida.\n   return `Siamo al passaggio: ${title}. ${instruction}${caution?' Attenzione: '+caution:''}. Se il testo non chiarisce il tuo dubbio, ferma il lavoro e chiedi a un tecnico.`;\n }\n function contextualAnswer(command){\n   // Solo testo della guida attualmente visualizzata. Nessun valore tecnico dedotto o inventato.\n   if(command==='caution'){\n     const caution=($('stepCaution')?.textContent||'').replace(/^ATTENZIONE\\s*[·:.-]?\\s*/i,'').trim();\n     return caution?`Precauzioni per questo passaggio: ${caution}`:'Non ho precauzioni specifiche verificate per questo passaggio. Consulta il manuale prima di procedere.';\n   }\n   if(command==='purpose'){\n     const goal=$('opGoal')?.textContent?.trim();\n     return goal?`Lo scopo della lavorazione è: ${goal}`:'Lo scopo non è disponibile nella procedura attuale.';\n   }\n   if(command==='method'){\n     const select=$('method');const label=select?.selectedOptions?.[0]?.textContent?.trim();\n     return label?`La modalità selezionata è: ${label}.`:'Non è stata individuata una modalità selezionata.';\n   }\n   if(command==='progress'){\n     const step=$('stepCount')?.textContent?.trim()||'';\n     const op=$('counter')?.textContent?.trim()||'';\n     const confirmed=$('stepProgress')?.textContent?.trim()||'';\n     return `${op}. ${step}. ${confirmed}`.trim()||'Non riesco a leggere lo stato di avanzamento.';\n   }\n   if(command==='help')return 'Puoi dire fatto, ripeti, indietro, aspetta, riprendiamo, spiegami meglio, quali precauzioni, qual è lo scopo, quale modalità, a che punto siamo, segnala un problema o ferma dialogo. Se segnali un problema, puoi descriverlo, confermarlo e registrarlo interamente a voce.';\n   return 'Non ho una risposta verificata.';\n }\n // Si usa sempre il ciclo parlato anche quando l'utente ha iniziato da \"Ascolta un comando\".\n function keepVoiceOpen(){\n   if(!active){active=true;paused=false;turn++;retries=0;refreshButtons();}\n }\n function cleanReport(text){\n   let s=String(text||'').trim();\n   s=s.replace(/^(?:(?:ho\\s+)?(?:finito|fatto|completato)|passaggio\\s+eseguito)\\s*[,!.;:]?\\s*(?:ma|per[oò])\\s+/i,'');\n   s=s.replace(/^(?:segnala(?:mi)?\\s+(?:un\\s+)?(?:problema|anomalia)|ho\\s+(?:un\\s+)?problema|c[’']?è\\s+(?:un\\s+)?problema)\\s*[,.:;-]?\\s*/i,'');\n   return s.trim().replace(/[.!?]+$/,'').trim();\n }\n function meaningfulReport(text){\n   const s=normalize(text);\n   if(s.length<7)return false;\n   if(/^(problema|un problema|anomalia|ho un problema|c e un problema|segnala un problema|un anomalia|una anomalia|ma ho un problema)$/.test(s))return false;\n   return true;\n }\n function currentOperation(){\n   const text=$('counter')?.textContent||'';\n   const match=text.match(/Operazione\\s+(\\d+)/i);\n   return match?Number(match[1]):0;\n }\n function riskFor(description){\n   return window.TagliandoContextHelp?.resolve(description,{\n     operation:currentOperation(),step:$('stepTitle')?.textContent||'',method:$('method')?.value||''\n   });\n }\n function anomalyAsk(text){\n   keepVoiceOpen();\n   setStatus('Segnalazione vocale in corso: ascolto e conferma senza toccare lo schermo.');\n   say(text,()=>{if(active)listen(true);});\n }\n function startAnomalyFlow(transcript,{critical=false,warning=''}={}){\n   const op=currentOperation();\n   let description=cleanReport(transcript);\n   if(!meaningfulReport(description))description='';\n   const danger=description?riskFor(description):null;\n   const isCritical=Boolean(critical||danger?.kind==='stop');\n   const advisory=isCritical?(warning||danger?.message||'Interrompi il lavoro.'):'';\n   anomalyFlow={stage:description?'confirm':'describe',description,critical:isCritical,warning:advisory,operation:op};\n   setDraft(description?`Segnalazione da confermare: ${description}`:'Segnalazione vocale: in attesa della descrizione.');\n   if(description){\n     anomalyAsk(`${advisory?advisory+' ':''}Ho rilevato questa anomalia: ${description}. Vuoi registrarla e sospendere la lavorazione? Dì registra, modifica oppure annulla segnalazione.`);\n   }else{\n     anomalyAsk(`${advisory?advisory+' ':''}Descrivi l'anomalia che hai riscontrato. Ti ascolto.`);\n   }\n }\n function cancelAnomalyFlow(){\n   const critical=Boolean(anomalyFlow?.critical);\n   anomalyFlow=null;setDraft('');\n   if(critical){\n     setStatus('Segnalazione annullata. Possibile pericolo: lavorazione non confermata.');\n     say('Segnalazione non registrata. Per sicurezza, non proseguire con questa lavorazione prima di una verifica.',()=>stopAll('Dialogo interrotto per precauzione. La lavorazione non è stata confermata.'));\n   }else{\n     setStatus('Segnalazione annullata. Nessuna operazione modificata.');\n     say('Segnalazione annullata. Riprendiamo dal passaggio corrente.',()=>describeNext());\n   }\n }\n function finishVoiceAnomaly(){\n   const flow=anomalyFlow;\n   if(!flow)return;\n   const api=window.TagliandoApp?.recordVoiceAnomaly;\n   if(typeof api!=='function'){\n     say('Non posso registrare la segnalazione in questo momento. Il lavoro rimane sospeso. Usa il registro manuale.',()=>stopAll('Registrazione non disponibile. Nessuna conferma eseguita.'));\n     return;\n   }\n   if(flow.operation!==currentOperation()){\n     say('Lavorazione cambiata durante la segnalazione. Nessuna anomalia registrata.',()=>stopAll('Segnalazione non registrata: operazione cambiata.'));\n     return;\n   }\n   const result=api(flow.description);\n   if(!result?.ok){\n     anomalyFlow.stage='describe';anomalyFlow.description='';setDraft('Segnalazione non salvata: ripeti la descrizione.');\n     anomalyAsk('La descrizione non è sufficiente. Descrivi nuovamente il problema.');\n     return;\n   }\n   anomalyFlow=null;setDraft('');\n   setStatus(`Anomalia registrata per l'operazione ${result.operation}. Lavorazione sospesa; dialogo fermato.`);\n   say(`Anomalia registrata. La lavorazione ${result.operation} è sospesa e il passaggio non viene confermato. Il dialogo è terminato.`,()=>stopAll(`Segnalazione salvata · operazione ${result.operation} sospesa.`));\n }\n function handleAnomalyResponse(transcript){\n   if(!anomalyFlow)return;\n   const s=normalize(transcript);\n   // Le parole di conferma sono valide esclusivamente nello stato di conferma,\n   // mai come comando «Fatto» durante la normale procedura.\n   if(/^(ferma dialogo|interrompi dialogo|stop dialogo|fermati|stop)$/.test(s)){\n     stopAll('Dialogo interrotto. Segnalazione non registrata.');return;\n   }\n   if(/^(annulla|annulla segnalazione|non registrare|lascia perdere|no annulla)$/.test(s)){\n     cancelAnomalyFlow();return;\n   }\n   if(anomalyFlow.stage==='describe'){\n     if(/^(ripeti|non ho capito|cosa devo dire)$/.test(s)){\n       anomalyAsk('Descrivi liberamente il problema riscontrato, ad esempio: la lama è crepata.');return;\n     }\n     const desc=cleanReport(transcript);\n     if(!meaningfulReport(desc)){\n       anomalyAsk('Non ho capito la descrizione. Dimmi quale componente presenta il problema e che cosa hai osservato.');return;\n     }\n     const risk=riskFor(desc);\n     anomalyFlow.description=desc;\n     if(risk?.kind==='stop'){anomalyFlow.critical=true;anomalyFlow.warning=risk.message;}\n     anomalyFlow.stage='confirm';\n     setDraft(`Segnalazione da confermare: ${desc}`);\n     anomalyAsk(`${risk?.kind==='stop'?risk.message+' ':''}Ho capito: ${desc}. Vuoi registrare questa anomalia? Dì registra, modifica oppure annulla segnalazione.`);\n     return;\n   }\n   if(anomalyFlow.stage==='confirm'){\n     if(/^(si|confermo|registra|registra anomalia|registra segnalazione|salva|salva segnalazione|va bene|esatto)$/.test(s)){\n       finishVoiceAnomaly();return;\n     }\n     if(/^(modifica|correggi|riformula|ripeti descrizione|voglio modificare)$/.test(s)){\n       anomalyFlow.stage='describe';anomalyFlow.description='';\n       setDraft('Segnalazione vocale: descrizione da modificare.');\n       anomalyAsk('Descrivi nuovamente l’anomalia, ti ascolto.');return;\n     }\n     anomalyAsk('Per evitare registrazioni errate, rispondi: registra, modifica oppure annulla segnalazione.');\n   }\n }\n function listenWhilePaused(automatic){\n   setStatus('In pausa. In ascolto per «Riprendiamo»; puoi anche premere «Ferma dialogo».');\n   if(automatic&&active)listen(true);\n }\n function describeNext(prefix=''){\n   if(!active)return;\n   setStatus(prefix+'Sto leggendo il passaggio; ascolterò dopo la lettura.');\n   say(speechText(),()=>listen(true));\n }\n function handle(transcript,automatic){\n   retries=0;\n   if(anomalyFlow){handleAnomalyResponse(transcript);return;}\n   const uncertain=ambiguousIntent(transcript);\n   if(uncertain){\n     const risk=riskFor(transcript);\n     if(risk?.kind==='stop'){\n       startAnomalyFlow(transcript,{critical:true,warning:risk.message});\n       return;\n     }\n     if(uncertain==='mixed'){\n       startAnomalyFlow(transcript);\n       return;\n     }\n     const msg=uncertain==='not-done'\n       ?'Ricevuto, il passaggio resta da completare. Dimmi fatto soltanto quando hai concluso; puoi anche dire aspetta o segnala un problema.'\n       :'La tua frase contiene sia un possibile completamento sia una difficoltà. Non registro il passaggio come eseguito. Se hai rilevato un problema, dì segnala un problema; altrimenti ripeti fatto solo dopo aver completato il lavoro.';\n     setStatus('Conferma non registrata: frase ambigua o lavoro non completato.');\n     if(automatic&&active)say(msg,()=>listen(true));else say(msg);\n     return;\n   }\n   const c=commandFor(transcript);\n   if(!c){\n     const contextual=riskFor(transcript);\n     if(contextual){\n       setStatus(contextual.kind==='stop'?'Possibile condizione critica: dialogo interrotto.':contextual.kind==='unknown'?'Richiesta fuori dalla base verificata.':'Chiarimento contestuale disponibile.');\n       if(contextual.kind==='stop'){\n         startAnomalyFlow(transcript,{critical:true,warning:contextual.message});\n       }else if(automatic&&active){say(contextual.message,()=>listen(true));}\n       else say(contextual.message);\n       return;\n     }\n     setStatus('Frase riconosciuta ma non prevista: nessuna azione eseguita.');\n     if(automatic&&active){\n       if(paused)listenWhilePaused(true);\n       else say('Non ho una risposta verificata per questa richiesta. Il passaggio non è stato modificato. Puoi dire ripeti, quali precauzioni oppure segnala un problema per interrompere e annotare la difficoltà.',()=>listen(true));\n     }\n     return;\n   }\n   if(c==='stop'){stopAll();return;}\n   if(c==='pause'){\n     paused=true;\n     if(automatic&&active){\n       setStatus('Dialogo in pausa: puoi dire «Riprendiamo».');\n       say('Va bene, aspetto. Quando sei pronto, pronuncia riprendiamo.',()=>listenWhilePaused(true));\n     }else setStatus('In pausa. Per riprendere, premi «Avvia dialogo».');\n     return;\n   }\n   if(c==='resume'){\n     paused=false;\n     if(automatic&&active)describeNext('Riprendiamo dal passaggio corrente. ');\n     else setStatus('Pronto: premi «Avvia dialogo» per continuare.');\n     return;\n   }\n   if(c==='anomaly'){\n     startAnomalyFlow(transcript);\n     return;\n   }\n   if(paused){\n     setStatus('Dialogo in pausa. Pronuncia «Riprendiamo» per continuare.');\n     if(automatic&&active)listenWhilePaused(true);\n     return;\n   }\n   if(['caution','purpose','method','progress','help'].includes(c)){\n     const response=contextualAnswer(c);\n     if(automatic&&active)say(response,()=>listen(true));\n     else {setStatus('Informazione letta dalla procedura corrente.');say(response);}\n     return;\n   }\n   if(c==='explain'){\n     if(automatic&&active)say(explainStep(),()=>listen(true));\n     else {setStatus('Spiegazione del passaggio corrente.');say(explainStep());}\n     return;\n   }\n   if(c==='repeat'){\n     if(automatic&&active)describeNext('Ripeto. ');\n     else {setStatus('Ripeto il passaggio.');say(speechText());}\n     return;\n   }\n   if(c==='back'){\n     if(!$('stepPrev').disabled){$('stepPrev').click();setStatus('Passaggio precedente.');}\n     else setStatus('Sei già al primo passaggio.');\n     if(automatic&&active)describeNext();return;\n   }\n   if(c==='done'){\n     const beforeOp=$('opTitle').textContent;\n     const beforeStep=$('stepTitle').textContent;\n     $('stepConfirm').click();\n     const afterOp=$('opTitle').textContent;\n     const afterStep=$('stepTitle').textContent;\n     if(automatic&&active){\n       if(beforeOp===afterOp&&beforeStep===afterStep){\n         stopAll('Non è stato rilevato un avanzamento: dialogo fermato per evitare conferme ripetute.');\n       }else if(beforeOp===afterOp){describeNext('Passaggio registrato. ');}\n       else {describeNext('Lavorazione completata. Passiamo alla successiva. ');}\n     }else setStatus('Conferma eseguita. Controlla la schermata.');\n   }\n }\n function listen(automatic){\n   if(listening||speaking)return;\n   if(!Engine){stopAll('Riconoscimento non disponibile su questo browser. Usa i comandi sullo schermo.');return;}\n   const cycle=turn;lastResult=false;lastError='';\n   try{\n     const r=new Engine();recognition=r;\n     r.lang='it-IT';r.interimResults=false;r.continuous=false;r.maxAlternatives=1;\n     r.onstart=()=>{if(cycle!==turn)return;listening=true;setStatus(paused?'In pausa: pronuncia «Riprendiamo».':'Ascolto attivo: pronuncia un comando.');refreshButtons();};\n     r.onresult=event=>{\n       if(cycle!==turn)return;\n       lastResult=true;\n       const words=event.results?.[0]?.[0]?.transcript||'';\n       setHeard(`Riconosciuto: «${words}»`);\n       // Non riavviare durante una sessione di riconoscimento ancora attiva.\n       r.__command=words;\n     };\n     r.onerror=e=>{if(cycle!==turn)return;lastError=e.error||'sconosciuto';};\n     r.onend=()=>{\n       if(cycle!==turn)return;\n       listening=false;recognition=null;refreshButtons();\n       if(lastResult){handle(r.__command||'',automatic);return;}\n       if(!automatic||!active){setStatus(lastError?`Ascolto terminato (${lastError}). Premi «Ascolta un comando» per riprovare.`:'Ascolto terminato senza comando.');return;}\n       if(lastError==='not-allowed'||lastError==='service-not-allowed'||lastError==='audio-capture'||lastError==='network'){\n         stopAll(`Ascolto non disponibile (${lastError}). Dialogo fermato; usa i pulsanti.`);return;\n       }\n       if(retries++>=2){stopAll('Non è stata rilevata una risposta. Il microfono è stato fermato; premi «Avvia dialogo» per riprendere.');return;}\n       setStatus('Nessun comando rilevato. Riprovo una volta…');\n       pendingRestart=setTimeout(()=>{pendingRestart=null;if(active&&cycle===turn)listen(true);},350);\n     };\n     setStatus(automatic?'Attivo il microfono…':'Attivo il microfono per un comando…');\n     r.start();\n   }catch(e){\n     recognition=null;listening=false;refreshButtons();\n     if(automatic)stopAll('Safari non ha consentito il riavvio automatico del microfono. Usa «Ascolta un comando» oppure riavvia il dialogo.');\n     else setStatus('Impossibile attivare il microfono. Verifica i permessi Safari.');\n   }\n }\n document.addEventListener('DOMContentLoaded',()=>{\n   $('voiceDialog').addEventListener('click',()=>{\n     if(active)return;\n     if(!Engine){setStatus('Il riconoscimento vocale non è disponibile su questo browser.');return;}\n     active=true;paused=false;turn++;retries=0;refreshButtons();setHeard('');describeNext();\n   });\n   $('voiceListen').addEventListener('click',()=>{if(active)stopAll('Dialogo continuo sospeso; ascolto manuale disponibile.');turn++;stopSpeech();listen(false);});\n   $('voiceRead').addEventListener('click',()=>{stopAll('Lettura del passaggio.');say(speechText());});\n   $('voiceStop').addEventListener('click',()=>stopAll());\n   document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&(active||listening||speaking))stopAll('App in background: audio e ascolto fermati per sicurezza.');});\n   window.addEventListener('pagehide',()=>{if(active||listening||speaking)stopAll('Dialogo fermato.');});\n   refreshButtons();setStatus(Engine?'Pronto. Tocca «Avvia dialogo» per iniziare. Disponibili pausa, chiarimenti e segnalazione vocale completa.':'Ascolto non disponibile qui; la guida manuale continua a funzionare.');\n });\n})();\n",
  "knowledge.js": "/* Assistente di officina — Fase 14.2 (sperimentale).\n * Base di conoscenza LOCALE, ricavata in sola lettura da OP in app.js.\n * Non conferma operazioni, non modifica sessioni, non invia dati a server.\n * Nessuna AI generativa e nessuna procedura certificata.\n */\n(() => {\n  'use strict';\n  const SCHEMA = 'tagliando.knowledge.v1';\n  const VERSION = '14.3.0';\n  const STATUS = 'DA_VALIDARE';\n  const CAUTION = 'Indicazione sperimentale da verificare sul manuale del modello effettivo.';\n  const text = v => String(v == null ? '' : v).trim();\n  const norm = v => text(v).toLocaleLowerCase('it-IT').normalize('NFD')\n    .replace(/[\\u0300-\\u036f]/g, '').replace(/[^a-z0-9 ]/g, ' ').replace(/\\s+/g, ' ').trim();\n  const skip = new Set('sono della delle degli dello dopo prima come cosa quale quali voglio vorrei posso devo serve fare faccio questo questa dove perche alla alle allo con nel nella nello una uno del dei per che hai sul sui gli cui piu non quando qual lavorazione passaggio'.split(' '));\n  const terms = v => norm(v).split(' ').filter(w => w.length >= 3 && !skip.has(w));\n  const pad = n => String(n).padStart(2, '0');\n\n  function build(operations) {\n    if (!Array.isArray(operations)) throw new TypeError('Archivio delle procedure non disponibile.');\n    return {\n      schema: SCHEMA,\n      version: VERSION,\n      sourceAppVersion: '0.12.1',\n      source: 'app.js / OP',\n      validation: STATUS,\n      procedures: operations.map(op => ({\n        id: 'RASA-OP-' + pad(op.id),\n        operationId: op.id,\n        title: text(op.title),\n        objective: text(op.goal),\n        context: text(op.context),\n        scope: 'manutenzione_preventiva_rasaerba_benzina',\n        source: {file: 'app.js', record: 'OP[id=' + op.id + ']'},\n        review: {status: STATUS, reviewer: null, reviewedAt: null, revision: null},\n        methods: (op.methods || []).map(m => ({id: text(m[0]), label: text(m[1])})),\n        steps: (op.steps || []).map((s, i) => ({\n          id: 'RASA-OP-' + pad(op.id) + '-P' + pad(i + 1),\n          index: i + 1,\n          title: text(s[0]),\n          instruction: text(s[1]),\n          warning: text(s[2]),\n          methods: text(s[3]).split('|').filter(Boolean),\n          source: {file: 'app.js', record: 'OP[id=' + op.id + '].steps[' + i + ']'},\n          review: {status: STATUS, reviewer: null, reviewedAt: null, revision: null}\n        }))\n      }))\n    };\n  }\n\n  function validate(kb) {\n    const errors = [];\n    if (!kb || kb.schema !== SCHEMA || !Array.isArray(kb.procedures)) {\n      return {ok: false, errors: ['Schema o elenco procedure non valido.'], procedureCount: 0, stepCount: 0};\n    }\n    if (kb.procedures.length !== 8) errors.push('Attese esattamente 8 procedure.');\n    const allIds = new Set(), opIds = new Set();\n    for (const op of kb.procedures) {\n      if (!Number.isInteger(op.operationId) || op.operationId < 1 || opIds.has(op.operationId)) errors.push('ID operazione non valido o duplicato.');\n      opIds.add(op.operationId);\n      if (allIds.has(op.id)) errors.push('ID ripetuto: ' + op.id);\n      allIds.add(op.id);\n      if (!op.title || !op.objective || !Array.isArray(op.steps) || !op.steps.length) errors.push('Procedura incompleta: ' + op.id);\n      const methods = new Set((op.methods || []).map(m => m.id));\n      if (!methods.size || methods.has('')) errors.push('Metodi assenti o non validi: ' + op.id);\n      for (const step of op.steps || []) {\n        if (!step.title || !step.instruction || !step.warning) errors.push('Passaggio incompleto: ' + step.id);\n        if (allIds.has(step.id)) errors.push('ID ripetuto: ' + step.id);\n        allIds.add(step.id);\n        if (!Array.isArray(step.methods)) errors.push('Elenco metodi non valido: ' + step.id);\n        else for (const m of step.methods) if (!methods.has(m)) errors.push('Metodo sconosciuto ' + m + ' in ' + step.id);\n      }\n    }\n    return {ok: errors.length === 0, errors, procedureCount: kb.procedures.length,\n      stepCount: kb.procedures.reduce((n, op) => n + (op.steps || []).length, 0)};\n  }\n\n  function activeSteps(op, method) {\n    if (!op || !Array.isArray(op.steps)) return [];\n    const allowed = (op.methods || []).some(m => m.id === method);\n    // Un metodo assente/non valido NON autorizza a mostrare passaggi esclusivi.\n    return op.steps.filter(s => !s.methods.length || (allowed && s.methods.includes(method)));\n  }\n\n  const dangers = [\n    {re: /\\b(lama|tagliente)\\b.*\\b(crep\\w*|fessur\\w*|rott\\w*|romp\\w*|lesionat\\w*|spezzat\\w*|piegat\\w*)\\b|\\b(crep\\w*|fessur\\w*|rott\\w*|romp\\w*|lesionat\\w*|spezzat\\w*|piegat\\w*)\\b.*\\b(lama|tagliente)\\b/,\n     message: 'Possibile lama danneggiata: non affilarla né rimontarla. Sospendi l’intervento e registra una segnalazione di sicurezza.'},\n    {re: /\\b(motore|leva|freno|comando)\\b.*\\b(non si spegne|non spegne|non si ferma|resta acceso|rimane acceso)\\b|\\b(non si spegne|non spegne|non si ferma|resta acceso|rimane acceso)\\b.*\\b(motore|leva|freno|comando)\\b/,\n     message: 'Possibile guasto al comando di arresto: non usare la macchina. Sospendi la lavorazione e registra l’anomalia.'},\n    {re: /\\b(perdita|perde|perdo|fuoriesce|gocciola|cola|sgocciola|puzza|odore forte|odore di)\\b.*\\b(benzina|carburante)\\b|\\b(benzina|carburante)\\b.*\\b(perdita|perde|perdo|fuoriesce|gocciola|cola|sgocciola|puzza|odore forte|odore di)\\b/,\n     message: 'Possibile perdita di carburante: ferma l’intervento, evita fonti di innesco e non avviare la macchina.'},\n    {re: /\\b(filetto|filettatura|sede candela)\\b.*\\b(spanat\\w*|rovinat\\w*|danneggiat\\w*)\\b|\\b(spanat\\w*|rovinat\\w*|danneggiat\\w*)\\b.*\\b(filetto|filettatura|sede candela)\\b/,\n     message: 'Possibile filettatura della candela danneggiata: non forzare il montaggio. Sospendi per verifica tecnica.'}\n  ];\n  const parameters = /\\b(coppia|serraggio in nm|newton metro|nm|gradazione|viscosita|capacita|quanti ml|quanto olio|quale olio|che olio|distanza elettrodi|intervallo di manutenzione|numero di giri|codice candela|codice filtro|quale candela|che candela|quale filtro|che filtro devo|quale lama|che ricambio|quale ricambio|quanto serrare|quanto stringere|a quanti newton|verso inclinare|ricambio compatibile|compatibilita|tempo di arresto|angolo esatto|quanti gradi)\\b/;\n  const repairs = /\\b(pulire il carburatore|riparare il carburatore|tarare il carburatore|regolare il carburatore|rimappare centralina|smontare il motore|riparare la frizione|riparare il cambio)\\b/;\n\n  function result(kind, message, sources) {\n    return {kind, text: message, sources: sources || [], stateChanged: false};\n  }\n  function answer(question, context = {}, database) {\n    const kb = database || getKnowledge();\n    const q = text(question).slice(0, 500), normalized = norm(q);\n    if (!q) return result('invalid', 'Inserisci una domanda tecnica.');\n    if (!validate(kb).ok) return result('unavailable', 'Archivio tecnico incoerente: consultazione bloccata.');\n    const hazard = dangers.find(x => x.re.test(normalized));\n    if (hazard) return result('stop', hazard.message);\n    if (repairs.test(normalized)) return result('unknown', 'Richiesta di riparazione fuori dalle otto procedure validate per la consultazione. Non fornisco istruzioni non verificate.');\n    if (parameters.test(normalized)) return result('model', 'Il dato dipende dal modello e non è verificato nella base attuale. Consulta il manuale del costruttore: non usare valori ipotetici.');\n\n    const current = kb.procedures.find(p => p.operationId === Number(context.operationId || context.operation));\n    const method = text(context.method);\n    const selected = current && activeSteps(current, method).find(s => norm(s.title) === norm(context.stepTitle) && text(context.stepTitle));\n    if (current && /\\b(scopo|obiettivo|a cosa serve)\\b/.test(normalized)) {\n      return result('reference', current.objective + '\\n\\n' + CAUTION, [current.id]);\n    }\n    if (selected && /\\b(precauzioni|rischi|avvertenze|sicurezza|cosa devo evitare)\\b/.test(normalized)) {\n      return result('reference', selected.warning + '\\n\\n' + CAUTION, [selected.id]);\n    }\n    if (selected && /\\b(spiegami|ripeti|chiarisci|passaggio corrente)\\b/.test(normalized)) {\n      return result('reference', selected.title + '. ' + selected.instruction + '\\n\\nAttenzione: ' + selected.warning + '\\n\\n' + CAUTION, [selected.id]);\n    }\n\n    const words = terms(q);\n    if (!words.length) return result('unknown', 'Domanda troppo generica: specifica componente e controllo desiderato.');\n    const matches = [];\n    for (const p of kb.procedures) {\n      // Per un'altra operazione o senza modalità conosciuta, solo passi comuni a tutte le modalità.\n      const available = activeSteps(p, current && p.operationId === current.operationId ? method : '');\n      for (const step of available) {\n        const titleWords = new Set(terms(p.title + ' ' + step.title));\n        const bodyWords = new Set(terms(p.objective + ' ' + step.instruction + ' ' + step.warning));\n        const titleMatches = words.filter(w => titleWords.has(w)).length;\n        const bodyMatches = words.filter(w => bodyWords.has(w)).length;\n        // Il solo contesto di sessione non costituisce evidenza di pertinenza.\n        if (titleMatches < 1 && bodyMatches < 2) continue;\n        const score = 5 * titleMatches + bodyMatches + (current && current.operationId === p.operationId ? 1 : 0);\n        matches.push({p, step, score});\n      }\n    }\n    matches.sort((a, b) => b.score - a.score);\n    const winner = matches[0];\n    // Query con un unico termine generico non autorizzano una procedura.\n    if (!winner || winner.score < 5 || (words.length === 1 && winner.score < 6)) {\n      return result('unknown', 'Nessun riferimento tecnico sufficientemente pertinente. Non deduco operazioni o valori mancanti.');\n    }\n    // Le risposte testuali riportano soltanto contenuto già presente nelle procedure.\n    return result('reference', winner.p.title + ' — ' + winner.step.title + '\\n\\n' +\n      winner.step.instruction + '\\n\\nAttenzione: ' + winner.step.warning + '\\n\\n' + CAUTION, [winner.step.id]);\n  }\n  function getKnowledge() {\n    if (typeof OP === 'undefined') throw new Error('Archivio OP non disponibile: caricare app.js prima di knowledge.js');\n    return build(OP);\n  }\n  window.TagliandoKnowledge = Object.freeze({\n    schema: SCHEMA, version: VERSION, status: STATUS,\n    build, validate, activeSteps, answer, getKnowledge\n  });\n})();",
  "retrieval.js": "/* Fase 14.3 — recupero deterministico di riferimenti tecnici, OFFLINE.\n * Modulo di ANTEPRIMA per futura integrazione AI: nessuna API, nessuna\n * mutazione dello stato dell'app e nessuna trasmissione di dati.\n * In presenza di contenuti DA_VALIDARE: externalTransmissionAllowed=false.\n */\n(() => {\n  'use strict';\n  const KB = window.TagliandoKnowledge;\n  if (!KB) throw new Error('Caricare knowledge.js prima di retrieval.js');\n  const SCHEMA = 'tagliando.retrieval.v1';\n  const MAX_QUERY = 500;\n  const MAX_REFERENCES = 3;\n  const LIMIT = 1800;\n  const normalize = x => String(x ?? '').toLocaleLowerCase('it-IT').normalize('NFD')\n    .replace(/[\\u0300-\\u036f]/g, '').replace(/[^a-z0-9 ]/g, ' ')\n    .replace(/\\s+/g, ' ').trim();\n  const stopwords = new Set('e ed o ma di del della delle degli dei da al allo alla alle il lo la i gli le un una uno in nel nell per con che cosa come quale quali quali sono ho hai avete posso devo fare faccio quale quando dove questo questa quella vorrei mi me si non su sul sulla ecco mio mia meglio spiegami dimmi serve vorrei voglio'.split(' '));\n  const stem = w => {\n    for (const prefix of ['affil','lav','sostitu','serr','mont','asciug','pul','lubrific','filtr','equilibr','sgrass','rimont']) {\n      if (w.startsWith(prefix)) return prefix;\n    }\n    return w;\n  };\n  const tokens = s => [...new Set(normalize(s).split(' ').filter(w => w.length >= 3 && !stopwords.has(w)).map(stem))];\n\n  // Lexical gates are deliberately conservative; they are NOT a certified safety detector.\n  const anchors = [\n    [1, /\\b(sottoscocca|scocca|incrostazion\\w*|erba sotto|pulizia della scocca)\\b/],\n    [2, /\\b(lama|lame|taglient\\w*|affilat\\w*|mozzo|portalama|equilibratur\\w*|bilanciament\\w*)\\b/],\n    [3, /\\b(filtro|filtri|prefiltro|spugna|elemento filtrante)\\b/],\n    [4, /\\b(candela|candele|pipetta|elettrodi|accensione)\\b/],\n    [5, /\\b(ruota|ruote|boccola|boccole|cuscinetto|cuscinetti)\\b/],\n    [6, /\\b(cavo|cavi|leveragg\\w*|comando di arresto|freno motore|fissaggi|viti)\\b/],\n    [7, /\\b(olio|lubrificant\\w*|astina|basamento)\\b/],\n    [8, /\\b(benzina|carburante|rimessaggio|vaschetta|stabilizzante|serbatoio)\\b/]\n  ];\n  const outside = /\\b(automobile|automobili|auto|cambio auto|cambio dell auto|frizione|centralina|motocicletta|moto|camion)\\b/;\n  const repair = /\\b(ripara\\w*|riparazione|revisiona\\w*|tarare|taratura|modificare|truccare|rimuovere la sicurezza)\\b/;\n  const specific = /\\b(quanto|quanti|quanta|quale|quali|dimmi)\\b.{0,55}\\b(nm|newton|coppia|serrare|stringere|gradi|angolo|ml|litri|olio|benzina|carburante|viscosita|candela|ricambio|filtro|lama|capacita|tipo|sigla|codice)\\b|\\b(quale olio|che olio|quale benzina|quanto carburante|quanta benzina|che candela|che filtro|coppia di serraggio|distanza elettrodi|capacita olio|gradazione|valore in nm|specifiche motore|codice ricambio|numero di giri|diametro esatto)\\b/;\n  const commands = /^(fatto|ho finito|avanti|indietro|salta|conferma|registra|ferma|riprendiamo|annulla|pausa|stop)\\b/;\n  const generic = /\\b(precauzioni|sicurezza|rischi|avvertenze|scopo|obiettivo|spiega\\w*|spiegami|ripeti|chiarisci|passaggio corrente|cosa devo fare)\\b/;\n\n  function envelope(decision, reason, extra = {}) {\n    return {\n      schema: SCHEMA,\n      decision,\n      reason,\n      aiReady: false,\n      externalTransmissionAllowed: false,\n      stateChanged: false,\n      sourceSchema: KB.schema,\n      references: [],\n      ...extra\n    };\n  }\n  function buildPreview(question, context = {}, database) {\n    const q = String(question ?? '').trim();\n    if (!q || q.length > MAX_QUERY) return envelope('REJECT', 'Domanda assente o superiore a 500 caratteri.');\n    let kb;\n    try { kb = database || KB.getKnowledge(); } catch (_) { return envelope('UNAVAILABLE', 'Base di conoscenza non accessibile.'); }\n    if (!KB.validate(kb).ok) return envelope('UNAVAILABLE', 'Archivio tecnico incoerente: retrieval bloccato.');\n\n    const core = KB.answer(q, context, kb);\n    if (core.kind === 'stop') return envelope('SAFETY_STOP', core.text);\n    const normalized = normalize(q);\n    if (core.kind === 'model' || specific.test(normalized)) {\n      return envelope('MODEL_REQUIRED', 'Parametro dipendente dal modello: usare il manuale del costruttore. Non inviare la richiesta al modello AI senza dati tecnici verificati.');\n    }\n    if (outside.test(normalized) || repair.test(normalized)) {\n      return envelope('OUT_OF_SCOPE', 'Riparazione o dominio non compresi nelle procedure preventive attuali.');\n    }\n    if (commands.test(normalized)) {\n      return envelope('COMMAND', 'I comandi operativi sono gestiti solo dal controllore deterministico, non dall’AI.');\n    }\n    const currentId = Number(context.operationId ?? context.operation);\n    const current = kb.procedures.find(p => p.operationId === currentId);\n    const method = String(context.method ?? '');\n    const selected = current && KB.activeSteps(current, method).find(s =>\n      String(context.stepTitle || '').trim() && normalize(s.title) === normalize(context.stepTitle));\n    const found = anchors.filter(([id, re]) => re.test(normalized)).map(([id]) => id);\n    // \"olio sul filtro\": due componenti, nessun contesto univoco: chiedere chiarimento.\n    let target = null;\n    if (found.length > 1) {\n      if (current && found.includes(currentId) && /\\b(questa|questo|qui|passaggio)\\b/.test(normalized)) target = current;\n      else return envelope('CLARIFY', 'Sono citate più lavorazioni. Specifica quale componente intendi.');\n    } else if (found.length === 1) target = kb.procedures.find(p => p.operationId === found[0]);\n    else if (selected && generic.test(normalized)) target = current;\n    else return envelope('NO_MATCH', 'Non è stato identificato un componente univoco nelle otto procedure.');\n    if (!target) return envelope('NO_MATCH', 'Lavorazione non presente nella base tecnica.');\n\n    // Sia operazione sia modalità devono coincidere; altrimenti solo passaggi comuni.\n    const selectedMethod = current && target.operationId === currentId ? method : '';\n    const candidates = KB.activeSteps(target, selectedMethod);\n    const qtokens = tokens(q);\n    const scoreFor = s => {\n      const title = new Set(tokens(s.title));\n      const body = new Set(tokens(s.instruction + ' ' + s.warning));\n      let score = qtokens.reduce((n, t) => n + (title.has(t) ? 6 : 0) + (body.has(t) ? 2 : 0), 0);\n      if (selected && target.id === current?.id && selected.id === s.id && generic.test(normalized)) score += 12;\n      return score;\n    };\n    const ranked = candidates.map(s => ({s, rank: scoreFor(s)}))\n      .sort((a, b) => b.rank - a.rank || a.s.index - b.s.index);\n    const meaningful = ranked.filter(x => x.rank > 0);\n    let rows;\n    if (meaningful.length) rows = meaningful.slice(0, MAX_REFERENCES);\n    else if (selected && target.id === current?.id && generic.test(normalized)) rows = [{s: selected, rank: 12}];\n    else return envelope('CLARIFY', 'Componente identificato, ma non trovo un passaggio preciso per la domanda.');\n\n    const references = [];\n    let length = 0;\n    for (const {s} of rows) {\n      const ref = {\n        id: s.id,\n        operationId: target.operationId,\n        operation: target.title,\n        method: selectedMethod || null,\n        step: s.title,\n        instruction: s.instruction,\n        warning: s.warning,\n        provenance: s.source,\n        reviewStatus: s.review.status\n      };\n      const size = JSON.stringify(ref).length;\n      if (length + size > LIMIT) break;\n      length += size;\n      references.push(ref);\n    }\n    if (!references.length) return envelope('UNAVAILABLE', 'Selezione troppo estesa o fuori dai limiti.');\n    const allReviewed = references.every(x => x.reviewStatus === 'VALIDATO');\n    // La validazione dei contenuti è necessaria, ma NON sufficiente per abilitare AI:\n    // il backend dovrà ripetere autorizzazione, policy e verifica fonti server-side.\n    return envelope('PREVIEW_ONLY', allReviewed\n      ? 'Riferimenti trovati; integrazione backend non ancora autorizzata.'\n      : 'Riferimenti trovati, ma ancora DA_VALIDARE. Non trasmettere al modello AI.', {\n        operation: {id: target.id, title: target.title},\n        context: {operationId: current ? current.operationId : null, method: selectedMethod || null,\n          stepId: selected?.id ?? null},\n        references,\n        referenceCount: references.length,\n        maxReferenceCount: MAX_REFERENCES\n      });\n  }\n  window.TagliandoRetrieval = Object.freeze({schema: SCHEMA, version:'14.3.0',\n    buildPreview, maxQueryLength:MAX_QUERY});\n})();",
  "knowledge-ui.js": "/* Fase 14.3 — Interfaccia sperimentale in sola lettura.\n * Non usa microfono, non invia richieste e non modifica lo stato della PWA.\n */\n(() => {\n  'use strict';\n  const engine = window.TagliandoKnowledge;\n  const retrieval = window.TagliandoRetrieval;\n  const anchor = document.getElementById('voicePanel');\n  if (!engine || !retrieval || !anchor || document.getElementById('knowledgePanel')) return;\n\n  const panel = document.createElement('section');\n  panel.className = 'panel';\n  panel.id = 'knowledgePanel';\n  panel.setAttribute('aria-label', 'Base di conoscenza sperimentale');\n  panel.innerHTML = [\n    '<h2>Base tecnica — Fase 14.3 (sperimentale)</h2>',\n    '<p class=\"muted small\">Consultazione locale delle otto procedure. Nessuna AI generativa collegata, nessuna modifica al tagliando.</p>',\n    '<p class=\"note\">TUTTI I CONTENUTI SONO DA VALIDARE. Attieniti al manuale del costruttore; non usare questo pannello come autorizzazione operativa.</p>',\n    '<label for=\"knowledgeQuestion\">Domanda tecnica</label>',\n    '<textarea id=\"knowledgeQuestion\" rows=\"2\" maxlength=\"500\" placeholder=\"Es. Quali precauzioni? Quale passaggio riguarda il filtro?\"></textarea>',\n    '<div class=\"actions\"><button id=\"knowledgeAsk\" type=\"button\" class=\"primary\">Consulta la base</button>',\n    '<button id=\"knowledgeExport\" type=\"button\">Esporta archivio JSON</button>',\n    '<button id=\"knowledgePreviewBtn\" type=\"button\">Anteprima riferimenti per AI</button></div>',\n    '<p id=\"knowledgeAnswer\" role=\"status\" aria-live=\"polite\" style=\"white-space:pre-wrap\"></p>',\n    '<p id=\"knowledgeSources\" class=\"muted small\"></p>',\n    '<p class=\"muted small\">Anteprima locale: i riferimenti non vengono trasmessi a nessun servizio AI. Tutti i contenuti rimangono DA_VALIDARE.</p>',\n    '<p id=\"knowledgePreview\" class=\"note\" role=\"status\" aria-live=\"polite\" style=\"white-space:pre-wrap;overflow-wrap:anywhere\"></p>'\n  ].join('');\n  anchor.insertAdjacentElement('afterend', panel);\n  const $ = id => document.getElementById(id);\n\n  function context() {\n    const count = $('counter')?.textContent || '';\n    const m = count.match(/Operazione\\s+(\\d+)/i);\n    return {\n      operationId: m ? Number(m[1]) : 0,\n      method: $('method')?.value || '',\n      stepTitle: $('stepTitle')?.textContent || ''\n    };\n  }\n  function ask() {\n    try {\n      const res = engine.answer($('knowledgeQuestion').value, context());\n      $('knowledgeAnswer').textContent = res.kind === 'stop' ? 'SOSPENDERE — ' + res.text : res.text;\n      $('knowledgeSources').textContent = res.sources.length\n        ? 'Riferimenti: ' + res.sources.join(', ') + ' · Stato: DA_VALIDARE'\n        : 'Nessun riferimento tecnico citabile. Nessuna operazione eseguita.';\n    } catch (_) {\n      $('knowledgeAnswer').textContent = 'Consultazione temporaneamente non disponibile.';\n      $('knowledgeSources').textContent = 'La sessione di manutenzione non è stata modificata.';\n    }\n  }\n  $('knowledgePreviewBtn').addEventListener('click', () => {\n    try {\n      const result = retrieval.buildPreview($('knowledgeQuestion').value, context());\n      const header = 'Esito: ' + result.decision + '\\n' + result.reason +\n        '\\nInvio a servizi esterni: DISABILITATO' +\n        '\\nModifica sessione: NO';\n      const refs = result.references.map(r => '\\n\\n' + r.id + ' · ' + r.operation + ' — ' +\n        r.step + ' (' + r.reviewStatus + ')\\n' + r.instruction +\n        '\\nAttenzione: ' + r.warning).join('');\n      $('knowledgePreview').textContent = header + refs;\n    } catch (_) {\n      $('knowledgePreview').textContent = 'Anteprima non disponibile: nessuna richiesta inviata.';\n    }\n  });\n  $('knowledgeAsk').addEventListener('click', ask);\n  $('knowledgeQuestion').addEventListener('keydown', event => {\n    if (event.key === 'Enter' && (event.ctrlKey || event.metaKey)) ask();\n  });\n\n  $('knowledgeExport').addEventListener('click', () => {\n    try {\n      const db = engine.getKnowledge(), report = engine.validate(db);\n      if (!report.ok) throw new Error('Verifica struttura non superata.');\n      const file = new Blob([JSON.stringify(db, null, 2)], {type: 'application/json;charset=utf-8'});\n      const url = URL.createObjectURL(file);\n      const link = document.createElement('a');\n      link.href = url;\n      link.download = 'tagliando-base-tecnica-DA_VALIDARE.json';\n      link.click();\n      setTimeout(() => URL.revokeObjectURL(url), 3000);\n      $('knowledgeSources').textContent = 'Esportazione: ' + report.procedureCount + ' procedure, ' +\n        report.stepCount + ' passaggi. Tutti DA_VALIDARE.';\n    } catch (_) {\n      $('knowledgeSources').textContent = 'Esportazione bloccata: archivio tecnico non coerente.';\n    }\n  });\n})();",
  "style.css": ":root{font-family:system-ui,-apple-system,\"Segoe UI\",sans-serif;color:#192d3a;background:#f4f6fa}*{box-sizing:border-box}body{margin:0}main{max-width:1100px;padding:26px 18px 55px;margin:auto}header{display:flex;justify-content:space-between;gap:10px;align-items:center;border-bottom:1px solid #d9e2e8;padding-bottom:15px}h1{font-size:clamp(28px,5vw,42px);letter-spacing:-.035em;margin:23px 0 7px}h2{font-size:21px;margin:0 0 13px}h3{font-size:17px;margin:0 0 10px}p{line-height:1.55}button{min-height:44px;background:#fff;border:1px solid #a9bac5;border-radius:10px;padding:10px 13px;color:#163449;font:inherit;font-weight:700;cursor:pointer}button.primary{background:#155e72;border-color:#155e72;color:white}button.danger{border-color:#b24b41;background:#fff7f4;color:#993526}button:disabled{opacity:.4;cursor:not-allowed}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #80c5e0;outline-offset:2px}.muted{color:#526776}.small{font-size:13px}.pill,.state{display:inline-block;background:#e6eff4;border-radius:99px;padding:6px 10px;font-size:12px;font-weight:800}.state.done{background:#def3e6;color:#126243}.state.skipped{background:#f7efdc;color:#7e5b0b}.state.stopped{background:#fde8e4;color:#912c27}.kicker{font-weight:800;font-size:12px;letter-spacing:.09em;color:#126078;text-transform:uppercase}.panel{background:#fff;border:1px solid #d9e3ea;padding:21px;border-radius:16px;margin:0 0 16px}.layout{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(260px,.85fr);gap:16px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:14px}.headrow{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.progress{height:10px;background:#e6edf1;overflow:hidden;border-radius:99px;margin:15px 0}.progress>div{height:100%;width:0;background:#16827d;transition:width .2s}.caution{background:#fff6e5;border:1px solid #ebd39b;border-radius:12px;padding:14px 16px;margin:17px 0}.system{background:#e9f4f4;border-radius:10px;padding:11px 14px;margin:15px 0;font-size:13px}.choice{background:#eef5f8;border-radius:12px;padding:12px;margin:18px 0}label{display:block;font-size:13px;font-weight:800;margin:11px 0 7px}input:not([type=checkbox]),select,textarea{width:100%;padding:12px;background:white;border:1px solid #b8c7d0;border-radius:10px;font:inherit}textarea{min-height:85px;resize:vertical}.step{border:1px solid #d6e0e7;background:#f9fbfd;border-radius:12px;padding:17px;margin:12px 0 16px}.step h3{font-size:20px;margin:9px 0}.note{background:#fff4df;border-left:4px solid #c58b2b;padding:12px;border-radius:4px;font-size:14px}.check{display:flex;align-items:flex-start;gap:10px;font-size:14px;font-weight:550;margin:16px 0}.check input{margin:3px 0 0;width:19px;height:19px;flex-shrink:0}.actions{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0 5px}.actions button{flex:1 1 140px}.oplist{padding:0;list-style:none;margin:0}.oplist li{border-top:1px solid #e8ecf0;padding:10px 2px;cursor:pointer}.oplist li.active{color:#126078;font-weight:800}.oplist li span{display:block;color:#607481;font-size:12px;padding-top:3px}.events{max-height:250px;overflow:auto;font-size:12px;color:#56707b}.events p{padding-bottom:7px;border-bottom:1px solid #e8eff2;margin:9px 0}footer{font-size:12px;color:#627682;margin-top:18px}@media(max-width:760px){.layout,.columns{grid-template-columns:1fr}.panel{padding:16px}.actions button{flex:1 1 130px}}\n\n/* v0.6: modalità banco per schermi piccoli e utilizzo in officina */\n.bench-toggle{width:100%;margin:4px 0 12px;background:#e4f3f4;border:2px solid #155e72;min-height:54px}\n.bench-controls{display:grid;grid-template-columns:1fr 1.6fr 1fr;gap:10px;margin:18px 0}\n.bench-controls button{min-height:66px;font-size:17px}\n#benchExit{width:100%;min-height:50px}\nbody.bench-mode main>header,body.bench-mode main>h1,body.bench-mode main>.muted,body.bench-mode main>.caution,body.bench-mode main>.system,body.bench-mode main>.panel,body.bench-mode main>footer,body.bench-mode .layout aside,body.bench-mode .layout>div>.panel:nth-child(2){display:none}\nbody.bench-mode main{max-width:800px;padding:14px 10px 35px}\nbody.bench-mode .layout{display:block}\nbody.bench-mode .layout>div>.panel:first-child{padding:14px}\nbody.bench-mode #opGoal,body.bench-mode #opContext,body.bench-mode .choice,body.bench-mode #note,body.bench-mode label[for=note],body.bench-mode #anomalyArea,body.bench-mode #complete,body.bench-mode #skip,body.bench-mode #anomalyStart,body.bench-mode #opPrev,body.bench-mode #opNext{display:none}\nbody.bench-mode .layout .actions{display:none}\nbody.bench-mode .step{padding:22px 18px;background:#fff;border:2px solid #155e72}\nbody.bench-mode .step #stepTitle{font-size:clamp(23px,5vw,32px)}\nbody.bench-mode .step #stepText{font-size:clamp(19px,4vw,26px);line-height:1.5}\nbody.bench-mode .step #stepCaution{font-size:17px;line-height:1.5}\nbody.bench-mode #benchActions{display:block !important}\nbody.bench-mode .step .check{font-size:16px}\nbody.bench-mode .bench-controls{display:grid}\n@media(max-width:530px){.bench-controls{grid-template-columns:1fr 1fr}.bench-controls #benchConfirm{grid-column:1/-1;grid-row:1}.bench-controls button{min-height:60px}}\n@media(prefers-reduced-motion:reduce){.progress>div{transition:none}}\n\n#benchUndo{width:100%;margin:8px 0 12px;background:#f4f6fa;min-height:48px}\n#stepUndo{background:#f4f6fa}\n\n/* Voce sperimentale: funzionalità accessoria, senza interferenze con il tagliando */\n.voice-actions{display:grid;gap:9px}.voice-actions button{min-height:49px}.voice-status{border-left:3px solid #155e72;padding:8px 10px;background:#eaf4f6;font-weight:600;line-height:1.4}.voice-panel strong{font-weight:700}\n\n/* v0.8: pannello voce sempre visibile anche in modalità banco */\n.voice-panel{border:2px solid #b6d9e0;background:#f4fbfc}\n.voice-actions{display:flex;flex-wrap:wrap;gap:8px}\n.voice-actions button{flex:1 1 155px}\n.voice-status{font-weight:700;border-radius:10px;padding:12px;background:#e5f0f5}\nbody.bench-mode #voicePanel{display:block;position:sticky;bottom:0;z-index:5;padding:12px;margin:12px 0;background:#f4fbfc;max-height:42vh;overflow:auto;box-shadow:0 -5px 18px #183c4a24}\nbody.bench-mode #voicePanel h2{font-size:16px;margin-bottom:5px}\nbody.bench-mode #voicePanel .muted{display:none}\nbody.bench-mode #voicePanel .voice-actions button{min-height:52px}\n@media(max-width:600px){.voice-actions button{flex:1 1 44%}}\n"
};
